-- Badawi Shop: the whole database in one file.
--
-- Paste this into the Supabase SQL editor and run it once. It is every migration in
-- supabase/migrations/ concatenated in order, so it does the same job as `npm run db:push`
-- without needing the CLI, a project link, or the database password.
--
-- Running it more than once is harmless: everything here is create-if-not-exists or replaced.
--
-- Generated by scripts/build-schema.mjs. Edit the migrations, not this file.

-- ==========================================================================
-- 20260825090000_core_schema.sql
-- ==========================================================================
-- Badawi Shop: core inventory schema.
-- USD is the single source of truth for every price. Amounts are integer cents so no total
-- ever depends on binary floating point. LBP is derived from app_settings at display time and
-- frozen onto each sale row at the moment it is taken.

create extension if not exists pg_trgm;

-- Keeps updated_at honest without the application having to remember.
create or replace function public.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- app_settings: exactly one row, enforced by the primary key check.
-- ---------------------------------------------------------------------------
create table if not exists public.app_settings (
  id               smallint primary key default 1 check (id = 1),
  shop_name        text        not null default 'Badawi Shop',
  usd_to_lbp_rate  numeric(14,4) not null default 89000 check (usd_to_lbp_rate > 0),
  lbp_rounding     integer     not null default 1000 check (lbp_rounding >= 1),
  rate_updated_at  timestamptz,
  updated_at       timestamptz not null default now()
);

drop trigger if exists app_settings_touch on public.app_settings;
create trigger app_settings_touch
  before update on public.app_settings
  for each row execute function public.touch_updated_at();

insert into public.app_settings (id) values (1) on conflict (id) do nothing;

-- ---------------------------------------------------------------------------
-- categories: the grouping used both to organise inventory and to browse in Sell mode.
-- ---------------------------------------------------------------------------
create table if not exists public.categories (
  id          uuid primary key default gen_random_uuid(),
  name        text        not null,
  color       text        not null default '#64748b',
  sort_order  integer     not null default 0,
  is_active   boolean     not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

-- Case-insensitive uniqueness: "Drinks" and "drinks" are the same shelf.
create unique index if not exists categories_name_unique
  on public.categories (lower(name));

create index if not exists categories_sort_idx
  on public.categories (sort_order, name) where is_active;

drop trigger if exists categories_touch on public.categories;
create trigger categories_touch
  before update on public.categories
  for each row execute function public.touch_updated_at();

-- ==========================================================================
-- 20260825090100_products.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- products: one row per article on the shelf.
-- barcode is nullable so loose goods, which are sold by tapping a category in Sell mode,
-- are first-class rather than a special case.
-- ---------------------------------------------------------------------------
create table if not exists public.products (
  id                   uuid primary key default gen_random_uuid(),
  barcode              text,
  name                 text          not null check (length(btrim(name)) > 0),
  category_id          uuid          references public.categories (id) on delete set null,
  cost_price_cents     integer       not null default 0 check (cost_price_cents >= 0),
  sale_price_cents     integer       not null default 0 check (sale_price_cents >= 0),
  quantity_in_stock    numeric(12,3) not null default 0,
  low_stock_threshold  numeric(12,3) not null default 0 check (low_stock_threshold >= 0),
  unit                 text          not null default 'piece',
  notes                text,
  is_active            boolean       not null default true,
  created_at           timestamptz   not null default now(),
  updated_at           timestamptz   not null default now()
);

-- A barcode identifies one article. Partial index so any number of products may have none.
create unique index if not exists products_barcode_unique
  on public.products (barcode) where barcode is not null;

create index if not exists products_category_idx
  on public.products (category_id) where is_active;

-- Trigram index backing the "search by name" box, which needs to match mid-word.
create index if not exists products_name_trgm_idx
  on public.products using gin (name gin_trgm_ops);

-- Drives the restocking list without a sequential scan over the catalogue.
create index if not exists products_low_stock_idx
  on public.products (quantity_in_stock) where is_active;

drop trigger if exists products_touch on public.products;
create trigger products_touch
  before update on public.products
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------------------
-- stock_movements: an append-only ledger of every change to a stock level, so a surprising
-- count can always be traced back to the sale or adjustment that caused it.
-- ---------------------------------------------------------------------------
create table if not exists public.stock_movements (
  id          uuid primary key default gen_random_uuid(),
  product_id  uuid          not null references public.products (id) on delete cascade,
  delta       numeric(12,3) not null,
  reason      text          not null check (reason in ('sale', 'restock', 'adjustment', 'initial')),
  sale_id     uuid,
  note        text,
  created_by  uuid          references auth.users (id) on delete set null,
  created_at  timestamptz   not null default now()
);

create index if not exists stock_movements_product_idx
  on public.stock_movements (product_id, created_at desc);

-- ==========================================================================
-- 20260825090200_sales.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- sales: one completed transaction.
-- The rate in force is frozen onto the row, so re-reading an old sale reproduces the exact
-- LBP figure the customer paid rather than re-converting it at today's rate.
-- ---------------------------------------------------------------------------
create table if not exists public.sales (
  id                uuid primary key default gen_random_uuid(),
  sold_at           timestamptz   not null default now(),
  subtotal_cents    integer       not null default 0 check (subtotal_cents >= 0),
  discount_type     text          not null default 'none'
                                  check (discount_type in ('none', 'percent', 'amount')),
  discount_value    numeric(12,2) not null default 0 check (discount_value >= 0),
  discount_cents    integer       not null default 0 check (discount_cents >= 0),
  total_cents       integer       not null default 0 check (total_cents >= 0),
  total_cost_cents  integer       not null default 0,
  profit_cents      integer       not null default 0,
  payment_currency  text          not null default 'USD' check (payment_currency in ('USD', 'LBP')),
  usd_to_lbp_rate   numeric(14,4) not null default 0,
  total_lbp         numeric(16,2) not null default 0,
  item_count        numeric(12,3) not null default 0,
  note              text,
  created_by        uuid          references auth.users (id) on delete set null,
  created_at        timestamptz   not null default now(),
  constraint sales_discount_within_subtotal check (discount_cents <= subtotal_cents)
);

-- Every report filters on sold_at, newest first.
create index if not exists sales_sold_at_idx on public.sales (sold_at desc);

-- ---------------------------------------------------------------------------
-- sale_items: the lines of a sale, with the product details copied in.
--
-- Snapshotting name, barcode, category, price and cost is what makes historical profit
-- correct: changing a price today, or deleting a product entirely, leaves last month's
-- numbers exactly as they were.
-- ---------------------------------------------------------------------------
create table if not exists public.sale_items (
  id                uuid primary key default gen_random_uuid(),
  sale_id           uuid          not null references public.sales (id) on delete cascade,
  product_id        uuid          references public.products (id) on delete set null,
  product_name      text          not null,
  barcode           text,
  category_name     text,
  unit              text          not null default 'piece',
  unit_price_cents  integer       not null check (unit_price_cents >= 0),
  unit_cost_cents   integer       not null check (unit_cost_cents >= 0),
  quantity          numeric(12,3) not null check (quantity > 0),
  line_total_cents  integer       not null,
  line_cost_cents   integer       not null,
  line_profit_cents integer       not null,
  created_at        timestamptz   not null default now()
);

create index if not exists sale_items_sale_idx on public.sale_items (sale_id);
create index if not exists sale_items_product_idx on public.sale_items (product_id);
-- Best-sellers group by the snapshotted name so deleted products still appear.
create index if not exists sale_items_name_idx on public.sale_items (product_name);

alter table public.stock_movements
  drop constraint if exists stock_movements_sale_id_fkey;
alter table public.stock_movements
  add constraint stock_movements_sale_id_fkey
  foreign key (sale_id) references public.sales (id) on delete set null;

-- ==========================================================================
-- 20260825090300_rls.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- Row level security.
--
-- The shop runs on one shared account, so the rule is simple: a signed-in session may work
-- with the whole catalogue, and an anonymous visitor may do nothing at all. The anon key
-- shipped in the browser bundle is therefore useless without a login.
--
-- Money tables are deliberately read-only from the client. Sales are written only through
-- checkout_sale, and stock only through checkout_sale or adjust_stock, both SECURITY DEFINER.
-- That means a total can never be posted from a device that computed it itself.
-- ---------------------------------------------------------------------------

alter table public.app_settings    enable row level security;
alter table public.categories      enable row level security;
alter table public.products        enable row level security;
alter table public.sales           enable row level security;
alter table public.sale_items      enable row level security;
alter table public.stock_movements enable row level security;

-- Settings: readable and tunable by the shop.
drop policy if exists app_settings_read on public.app_settings;
create policy app_settings_read on public.app_settings
  for select to authenticated using (true);
drop policy if exists app_settings_update on public.app_settings;
create policy app_settings_update on public.app_settings
  for update to authenticated using (true) with check (true);

-- Categories: full control.
drop policy if exists categories_read on public.categories;
create policy categories_read on public.categories
  for select to authenticated using (true);
drop policy if exists categories_insert on public.categories;
create policy categories_insert on public.categories
  for insert to authenticated with check (true);
drop policy if exists categories_update on public.categories;
create policy categories_update on public.categories
  for update to authenticated using (true) with check (true);
drop policy if exists categories_delete on public.categories;
create policy categories_delete on public.categories
  for delete to authenticated using (true);

-- Products: full control. Stock is edited through adjust_stock, but the rest of the record
-- is ordinary data the shop maintains directly.
drop policy if exists products_read on public.products;
create policy products_read on public.products
  for select to authenticated using (true);
drop policy if exists products_insert on public.products;
create policy products_insert on public.products
  for insert to authenticated with check (true);
drop policy if exists products_update on public.products;
create policy products_update on public.products
  for update to authenticated using (true) with check (true);
drop policy if exists products_delete on public.products;
create policy products_delete on public.products
  for delete to authenticated using (true);

-- Sales and their lines: readable for reporting, never written directly.
drop policy if exists sales_read on public.sales;
create policy sales_read on public.sales
  for select to authenticated using (true);
drop policy if exists sale_items_read on public.sale_items;
create policy sale_items_read on public.sale_items
  for select to authenticated using (true);

-- The stock ledger is an audit trail: readable, append-only through the functions.
drop policy if exists stock_movements_read on public.stock_movements;
create policy stock_movements_read on public.stock_movements
  for select to authenticated using (true);

-- ==========================================================================
-- 20260825090400_checkout.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- checkout_sale: turns a basket into a sale, atomically.
--
-- The client sends product ids, quantities and the discount the cashier chose. It does NOT
-- send any price or total. Everything is recomputed here from the catalogue, so a tampered
-- or merely stale device cannot post a wrong figure.
--
-- Rows are locked in product-id order, which means two tills checking out overlapping
-- baskets at the same moment queue up instead of deadlocking, and the second one sees the
-- stock the first one already took.
--
-- Raises SQLSTATE BS001 when the shelf cannot cover the basket.
-- ---------------------------------------------------------------------------
create or replace function public.checkout_sale(
  p_items            jsonb,
  p_discount_type    text default 'none',
  p_discount_value   numeric default 0,
  p_payment_currency text default 'USD',
  p_note             text default null
) returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_sale_id        uuid := gen_random_uuid();
  v_settings       public.app_settings%rowtype;
  v_line           record;
  v_product        record;
  v_subtotal       bigint := 0;
  v_cost           bigint := 0;
  v_items          numeric := 0;
  v_line_total     bigint;
  v_line_cost      bigint;
  v_discount_cents bigint := 0;
  v_total          bigint;
  v_total_lbp      numeric;
begin
  if auth.uid() is null then
    raise exception 'You must be signed in to take a sale' using errcode = '42501';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Cannot check out an empty cart' using errcode = '22023';
  end if;

  if p_discount_type not in ('none', 'percent', 'amount') then
    raise exception 'Unknown discount type %', p_discount_type using errcode = '22023';
  end if;

  if p_payment_currency not in ('USD', 'LBP') then
    raise exception 'Unknown payment currency %', p_payment_currency using errcode = '22023';
  end if;

  select * into v_settings from public.app_settings where id = 1;

  insert into public.sales (id, payment_currency, discount_type, discount_value, note,
                            usd_to_lbp_rate, created_by)
  values (v_sale_id, p_payment_currency, p_discount_type, greatest(coalesce(p_discount_value, 0), 0),
          nullif(btrim(coalesce(p_note, '')), ''), v_settings.usd_to_lbp_rate, auth.uid());

  -- Duplicate ids in the payload are folded together, so scanning the same item twice in two
  -- separate lines still results in one sale line and one stock deduction.
  for v_line in
    select (elem ->> 'product_id')::uuid as product_id,
           sum((elem ->> 'quantity')::numeric) as quantity
    from jsonb_array_elements(p_items) as elem
    group by 1
    order by 1
  loop
    if v_line.quantity is null or v_line.quantity <= 0 then
      raise exception 'Quantity must be greater than zero' using errcode = '22023';
    end if;

    select p.*, c.name as category_name
      into v_product
      from public.products p
      left join public.categories c on c.id = p.category_id
     where p.id = v_line.product_id
     for update of p;

    if not found then
      raise exception 'That product no longer exists' using errcode = '23503';
    end if;

    if v_product.quantity_in_stock < v_line.quantity then
      raise exception 'Only % % of "%" left in stock, % requested',
        v_product.quantity_in_stock, v_product.unit, v_product.name, v_line.quantity
        using errcode = 'BS001';
    end if;

    v_line_total := round(v_product.sale_price_cents * v_line.quantity);
    v_line_cost  := round(v_product.cost_price_cents * v_line.quantity);

    insert into public.sale_items (
      sale_id, product_id, product_name, barcode, category_name, unit,
      unit_price_cents, unit_cost_cents, quantity,
      line_total_cents, line_cost_cents, line_profit_cents
    ) values (
      v_sale_id, v_product.id, v_product.name, v_product.barcode, v_product.category_name,
      v_product.unit, v_product.sale_price_cents, v_product.cost_price_cents, v_line.quantity,
      v_line_total, v_line_cost, v_line_total - v_line_cost
    );

    update public.products
       set quantity_in_stock = quantity_in_stock - v_line.quantity
     where id = v_product.id;

    insert into public.stock_movements (product_id, delta, reason, sale_id, created_by)
    values (v_product.id, -v_line.quantity, 'sale', v_sale_id, auth.uid());

    v_subtotal := v_subtotal + v_line_total;
    v_cost     := v_cost + v_line_cost;
    v_items    := v_items + v_line.quantity;
  end loop;

  -- The discount is applied to the recomputed subtotal and clamped, so it can never turn a
  -- sale into a payout however the request was crafted.
  v_discount_cents := case p_discount_type
    when 'percent' then round(v_subtotal * least(greatest(coalesce(p_discount_value, 0), 0), 100) / 100.0)
    when 'amount'  then round(greatest(coalesce(p_discount_value, 0), 0) * 100)
    else 0
  end;
  v_discount_cents := least(v_discount_cents, v_subtotal);

  v_total := v_subtotal - v_discount_cents;
  v_total_lbp := round((v_total / 100.0) * v_settings.usd_to_lbp_rate / v_settings.lbp_rounding)
                 * v_settings.lbp_rounding;

  update public.sales
     set subtotal_cents   = v_subtotal,
         discount_cents   = v_discount_cents,
         total_cents      = v_total,
         total_cost_cents = v_cost,
         profit_cents     = v_total - v_cost,
         item_count       = v_items,
         total_lbp        = v_total_lbp
   where id = v_sale_id;

  return v_sale_id;
end;
$$;

revoke all on function public.checkout_sale(jsonb, text, numeric, text, text) from public, anon;
grant execute on function public.checkout_sale(jsonb, text, numeric, text, text) to authenticated;

-- ==========================================================================
-- 20260825090500_adjust_stock.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- adjust_stock: the one way stock moves outside of a sale.
--
-- Restocking a shelf and correcting a miscount are the same operation with a different
-- reason, and both must write the ledger entry in the same transaction as the stock change,
-- which is why neither is a plain UPDATE from the client.
-- ---------------------------------------------------------------------------
create or replace function public.adjust_stock(
  p_product_id uuid,
  p_delta      numeric,
  p_reason     text default 'restock',
  p_note       text default null
) returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_product public.products%rowtype;
  v_new     numeric;
begin
  if auth.uid() is null then
    raise exception 'You must be signed in to change stock' using errcode = '42501';
  end if;

  if p_reason not in ('restock', 'adjustment', 'initial') then
    raise exception 'Unknown stock reason %', p_reason using errcode = '22023';
  end if;

  if p_delta is null or p_delta = 0 then
    raise exception 'Stock change must be a non-zero amount' using errcode = '22023';
  end if;

  select * into v_product from public.products where id = p_product_id for update;

  if not found then
    raise exception 'That product no longer exists' using errcode = '23503';
  end if;

  v_new := v_product.quantity_in_stock + p_delta;

  if v_new < 0 then
    raise exception 'That would leave "%" at % %, below zero',
      v_product.name, v_new, v_product.unit using errcode = 'BS001';
  end if;

  update public.products set quantity_in_stock = v_new where id = p_product_id;

  insert into public.stock_movements (product_id, delta, reason, note, created_by)
  values (p_product_id, p_delta, p_reason, nullif(btrim(coalesce(p_note, '')), ''), auth.uid());

  return v_new;
end;
$$;

revoke all on function public.adjust_stock(uuid, numeric, text, text) from public, anon;
grant execute on function public.adjust_stock(uuid, numeric, text, text) to authenticated;

-- ==========================================================================
-- 20260825090600_report_view.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- sale_line_facts: the single shape every report reads from.
--
-- A discount is taken against the whole basket, but reporting needs to know what each
-- product actually earned. The discount is therefore spread across the lines in proportion
-- to their value, so revenue per product, per category and per day all add back up to the
-- sale total instead of overstating it by the discount.
--
-- security_invoker means the view is subject to the same row level security as the tables
-- underneath it, rather than quietly running with the owner rights.
-- ---------------------------------------------------------------------------
-- Dropped first rather than replaced. A later migration widens this view, and CREATE OR
-- REPLACE VIEW refuses to hand back a column it did not have before, so replaying the whole
-- schema over an up-to-date database failed here. Dropping makes each replay define the view
-- from scratch, whatever shape it was left in.
drop view if exists public.sale_line_facts;

create view public.sale_line_facts
with (security_invoker = on) as
select
  si.id,
  si.sale_id,
  s.sold_at,
  s.payment_currency,
  si.product_id,
  si.product_name,
  si.barcode,
  coalesce(si.category_name, 'Uncategorised') as category_name,
  si.unit,
  si.quantity,
  si.unit_price_cents,
  si.unit_cost_cents,
  si.line_total_cents as gross_cents,
  si.line_cost_cents  as cost_cents,
  (si.line_total_cents - case
     when s.subtotal_cents > 0
       then round(s.discount_cents::numeric * si.line_total_cents / s.subtotal_cents)
     else 0
   end)::bigint as net_cents,
  (si.line_total_cents - case
     when s.subtotal_cents > 0
       then round(s.discount_cents::numeric * si.line_total_cents / s.subtotal_cents)
     else 0
   end - si.line_cost_cents)::bigint as net_profit_cents
from public.sale_items si
join public.sales s on s.id = si.sale_id;

grant select on public.sale_line_facts to authenticated;

-- ==========================================================================
-- 20260825090700_reports.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- Reporting functions. Aggregation happens in Postgres so the phone downloads a handful of
-- rows rather than the sales table.
-- ---------------------------------------------------------------------------

-- Dropped first rather than replaced. A later migration widens what this returns, and
-- CREATE OR REPLACE FUNCTION cannot change a return type, so replaying the whole schema
-- over an up-to-date database failed here.
drop function if exists public.report_summary(timestamptz, timestamptz);

create or replace function public.report_summary(p_from timestamptz, p_to timestamptz)
returns table (
  total_sales_cents    bigint,
  total_cost_cents     bigint,
  total_profit_cents   bigint,
  total_discount_cents bigint,
  transaction_count    bigint,
  items_sold           numeric,
  paid_usd_cents       bigint,
  paid_lbp_cents       bigint
)
language sql
stable
as $$
  select
    coalesce(sum(total_cents), 0)::bigint,
    coalesce(sum(total_cost_cents), 0)::bigint,
    coalesce(sum(profit_cents), 0)::bigint,
    coalesce(sum(discount_cents), 0)::bigint,
    count(*)::bigint,
    coalesce(sum(item_count), 0)::numeric,
    coalesce(sum(total_cents) filter (where payment_currency = 'USD'), 0)::bigint,
    coalesce(sum(total_cents) filter (where payment_currency = 'LBP'), 0)::bigint
  from public.sales
  where sold_at >= p_from and sold_at < p_to;
$$;

-- Best sellers. Grouped on the snapshotted name so an article that has since been deleted
-- still shows up in the month it sold.
create or replace function public.report_top_products(
  p_from timestamptz, p_to timestamptz, p_limit integer default 20
)
returns table (
  product_id    uuid,
  product_name  text,
  barcode       text,
  category_name text,
  quantity_sold numeric,
  revenue_cents bigint,
  profit_cents  bigint
)
language sql
stable
as $$
  select
    (array_agg(f.product_id) filter (where f.product_id is not null))[1],
    f.product_name,
    max(f.barcode),
    max(f.category_name),
    sum(f.quantity)::numeric,
    sum(f.net_cents)::bigint,
    sum(f.net_profit_cents)::bigint
  from public.sale_line_facts f
  where f.sold_at >= p_from and f.sold_at < p_to
  group by f.product_name
  order by sum(f.quantity) desc, sum(f.net_cents) desc
  limit greatest(coalesce(p_limit, 20), 1);
$$;

create or replace function public.report_by_category(p_from timestamptz, p_to timestamptz)
returns table (
  category_name text,
  quantity_sold numeric,
  revenue_cents bigint,
  profit_cents  bigint
)
language sql
stable
as $$
  select
    f.category_name,
    sum(f.quantity)::numeric,
    sum(f.net_cents)::bigint,
    sum(f.net_profit_cents)::bigint
  from public.sale_line_facts f
  where f.sold_at >= p_from and f.sold_at < p_to
  group by f.category_name
  order by sum(f.net_cents) desc;
$$;

-- ==========================================================================
-- 20260825090800_report_series.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- report_time_series: the trend behind the chart, and the row-per-period grouping the Excel
-- export uses for its daily, weekly and monthly views.
--
-- Buckets are cut in the shop local time zone, not UTC. Without that, an evening sale in
-- Beirut lands in the following day and the daily totals quietly disagree with the till.
--
-- Empty periods come back as explicit zeroes so a quiet Sunday is a visible gap in the chart
-- rather than a missing point the line skips over.
-- ---------------------------------------------------------------------------
create or replace function public.report_time_series(
  p_from     timestamptz,
  p_to       timestamptz,
  p_bucket   text default 'daily',
  p_timezone text default 'UTC'
)
returns table (
  bucket_start      timestamptz,
  sales_cents       bigint,
  profit_cents      bigint,
  transaction_count bigint,
  items_sold        numeric
)
language plpgsql
stable
as $$
declare
  v_unit text;
  v_step interval;
begin
  if p_bucket not in ('daily', 'weekly', 'monthly') then
    raise exception 'Unknown report bucket %', p_bucket using errcode = '22023';
  end if;

  v_unit := case p_bucket when 'weekly' then 'week' when 'monthly' then 'month' else 'day' end;
  v_step := case v_unit when 'week' then interval '1 week'
                        when 'month' then interval '1 month'
                        else interval '1 day' end;

  return query
  with periods as (
    select generate_series(
             date_trunc(v_unit, (p_from at time zone p_timezone)),
             date_trunc(v_unit, ((p_to - interval '1 microsecond') at time zone p_timezone)),
             v_step
           ) as bucket
  ),
  totals as (
    select date_trunc(v_unit, (s.sold_at at time zone p_timezone)) as bucket,
           sum(s.total_cents)::bigint  as sales,
           sum(s.profit_cents)::bigint as profit,
           count(*)::bigint            as txns,
           sum(s.item_count)::numeric  as items
    from public.sales s
    where s.sold_at >= p_from and s.sold_at < p_to
    group by 1
  )
  select (periods.bucket at time zone p_timezone)::timestamptz,
         coalesce(totals.sales, 0)::bigint,
         coalesce(totals.profit, 0)::bigint,
         coalesce(totals.txns, 0)::bigint,
         coalesce(totals.items, 0)::numeric
  from periods
  left join totals on totals.bucket = periods.bucket
  order by periods.bucket;
end;
$$;

-- The restocking list.
create or replace function public.report_low_stock()
returns table (
  product_id    uuid,
  product_name  text,
  barcode       text,
  category_name text,
  stock         numeric,
  threshold     numeric,
  unit          text
)
language sql
stable
as $$
  select p.id,
         p.name,
         p.barcode,
         coalesce(c.name, 'Uncategorised'),
         p.quantity_in_stock,
         p.low_stock_threshold,
         p.unit
  from public.products p
  left join public.categories c on c.id = p.category_id
  where p.is_active
    and p.quantity_in_stock <= p.low_stock_threshold
  order by (p.quantity_in_stock <= 0) desc, p.quantity_in_stock asc, p.name asc;
$$;

-- ==========================================================================
-- 20260825090900_grants.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- Nothing in this system is reachable without a session. Reporting functions run as the
-- caller, so row level security still applies inside them.
-- ---------------------------------------------------------------------------
do $$
declare
  fn text;
begin
  foreach fn in array array[
    'public.report_summary(timestamptz, timestamptz)',
    'public.report_top_products(timestamptz, timestamptz, integer)',
    'public.report_by_category(timestamptz, timestamptz)',
    'public.report_time_series(timestamptz, timestamptz, text, text)',
    'public.report_low_stock()'
  ]
  loop
    execute format('revoke all on function %s from public, anon', fn);
    execute format('grant execute on function %s to authenticated', fn);
  end loop;
end;
$$;

-- ==========================================================================
-- 20260825091000_seed_categories.sql
-- ==========================================================================
-- A starting set of shelves so Sell mode is usable the moment the first product is added.
-- Renaming or deleting any of these from the app is expected.
insert into public.categories (name, color, sort_order) values
  ('Drinks',      '#0ea5e9', 10),
  ('Snacks',      '#f59e0b', 20),
  ('Groceries',   '#22c55e', 30),
  ('Dairy',       '#60a5fa', 40),
  ('Bakery',      '#d97706', 50),
  ('Household',   '#8b5cf6', 60),
  ('Personal Care','#ec4899', 70),
  ('Tobacco',     '#78716c', 80),
  ('Other',       '#64748b', 90)
on conflict do nothing;

-- ==========================================================================
-- 20260825091100_table_grants.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- Table privileges.
--
-- Row level security decides *which rows* a role may see. It has nothing to say about
-- whether that role may touch the table in the first place: that is an ordinary GRANT, and
-- without one Postgres refuses with "permission denied for table" before any policy is
-- consulted.
--
-- Supabase projects have historically handed these out by default, so it is easy to write a
-- schema that works in one project and fails in another. Granting them here explicitly makes
-- the schema self-contained and means it behaves the same wherever it is applied.
--
-- The grants deliberately mirror the policies exactly, so the two cannot drift apart:
-- anything the policies forbid is not granted either.
--
-- Each one is preceded by a revoke, because Supabase hands new tables a blanket GRANT ALL to
-- authenticated. Granting on top of that changes nothing: the role keeps TRUNCATE, and
-- TRUNCATE is not filtered by row level security the way select, insert, update and delete
-- are. A policy saying "sales are read-only" is no obstacle to emptying the table outright.
-- Revoking first makes the end state exactly what is written here, whatever the project
-- handed out beforehand.
-- ---------------------------------------------------------------------------

grant usage on schema public to authenticated;

revoke all on public.app_settings    from authenticated;
revoke all on public.categories      from authenticated;
revoke all on public.products        from authenticated;
revoke all on public.sales           from authenticated;
revoke all on public.sale_items      from authenticated;
revoke all on public.stock_movements from authenticated;
revoke all on public.sale_line_facts from authenticated;

-- Settings: the shop reads them everywhere and edits the rate.
grant select, update on public.app_settings to authenticated;

-- Categories and products are ordinary records the shop maintains.
grant select, insert, update, delete on public.categories to authenticated;
grant select, insert, update, delete on public.products   to authenticated;

-- Money is read-only from the client. Sales are written only by checkout_sale, and the
-- stock ledger only by checkout_sale and adjust_stock, both of which run as the owner.
grant select on public.sales           to authenticated;
grant select on public.sale_items      to authenticated;
grant select on public.stock_movements to authenticated;
grant select on public.sale_line_facts to authenticated;

-- ---------------------------------------------------------------------------
-- And nothing at all for anonymous callers.
--
-- The anon key ships inside the app bundle and inside the APK, so it is public by
-- definition. It must be worthless without a session. This is belt and braces over the
-- policies, which already grant anon nothing: a future table added without a policy would
-- still be unreachable.
-- ---------------------------------------------------------------------------
revoke all on all tables in schema public from anon;
revoke all on all sequences in schema public from anon;
revoke all on all functions in schema public from anon;

-- ==========================================================================
-- 20260828090000_cash_ledger.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- cash_movements: where the shop's money went.
--
-- A running cash box. Takings go in, restocking takes out, and the balance is what is
-- available to spend on the next delivery.
--
-- Sales add the full amount the customer paid, not the profit on it. That sounds wrong until
-- you follow one item through: sell for $100 having paid $60, then buy another for $60. Add
-- the takings and subtract the purchase and the box holds $40, which is the profit. Add only
-- the profit and subtract the purchase and it holds -$20, having charged the $60 twice.
--
-- Amounts are signed: positive is money in, negative is money out. The balance is their sum,
-- so it can always be explained by listing the rows that made it.
--
-- Everything is in USD cents like the rest of the system, whichever currency was handed over.
-- ---------------------------------------------------------------------------
create table if not exists public.cash_movements (
  id            uuid primary key default gen_random_uuid(),
  kind          text        not null check (kind in ('sale', 'restock', 'investment')),
  amount_cents  bigint      not null,
  sale_id       uuid        references public.sales (id) on delete cascade,
  product_id    uuid        references public.products (id) on delete set null,
  product_name  text,
  note          text,
  created_by    uuid        references auth.users (id) on delete set null,
  created_at    timestamptz not null default now(),

  -- Money in is positive, money out is negative. Nothing else makes sense per kind.
  constraint cash_direction check (
    (kind = 'sale'       and amount_cents >= 0) or
    (kind = 'investment' and amount_cents >= 0) or
    (kind = 'restock'    and amount_cents <= 0)
  )
);

create index if not exists cash_movements_created_idx
  on public.cash_movements (created_at desc);

alter table public.cash_movements enable row level security;

drop policy if exists cash_movements_read on public.cash_movements;
create policy cash_movements_read on public.cash_movements
  for select to authenticated using (true);

-- Written only by checkout_sale and adjust_stock, both of which run as the owner, so the
-- balance can never be moved by a device posting a figure of its own.
revoke all on public.cash_movements from authenticated;
grant select on public.cash_movements to authenticated;
revoke all on public.cash_movements from anon;

-- ==========================================================================
-- 20260828090100_checkout_cash.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- checkout_sale, now also putting the takings in the cash box.
--
-- Identical to before except for the one insert at the end. It stays inside the same
-- transaction as the sale, so the books and the cash box can never disagree: if the sale is
-- rolled back for want of stock, the money never went in either.
-- ---------------------------------------------------------------------------
create or replace function public.checkout_sale(
  p_items            jsonb,
  p_discount_type    text default 'none',
  p_discount_value   numeric default 0,
  p_payment_currency text default 'USD',
  p_note             text default null
) returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_sale_id        uuid := gen_random_uuid();
  v_settings       public.app_settings%rowtype;
  v_line           record;
  v_product        record;
  v_subtotal       bigint := 0;
  v_cost           bigint := 0;
  v_items          numeric := 0;
  v_line_total     bigint;
  v_line_cost      bigint;
  v_discount_cents bigint := 0;
  v_total          bigint;
  v_total_lbp      numeric;
begin
  if auth.uid() is null then
    raise exception 'You must be signed in to take a sale' using errcode = '42501';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Cannot check out an empty cart' using errcode = '22023';
  end if;

  if p_discount_type not in ('none', 'percent', 'amount') then
    raise exception 'Unknown discount type %', p_discount_type using errcode = '22023';
  end if;

  if p_payment_currency not in ('USD', 'LBP') then
    raise exception 'Unknown payment currency %', p_payment_currency using errcode = '22023';
  end if;

  select * into v_settings from public.app_settings where id = 1;

  insert into public.sales (id, payment_currency, discount_type, discount_value, note,
                            usd_to_lbp_rate, created_by)
  values (v_sale_id, p_payment_currency, p_discount_type, greatest(coalesce(p_discount_value, 0), 0),
          nullif(btrim(coalesce(p_note, '')), ''), v_settings.usd_to_lbp_rate, auth.uid());

  for v_line in
    select (elem ->> 'product_id')::uuid as product_id,
           sum((elem ->> 'quantity')::numeric) as quantity
    from jsonb_array_elements(p_items) as elem
    group by 1
    order by 1
  loop
    if v_line.quantity is null or v_line.quantity <= 0 then
      raise exception 'Quantity must be greater than zero' using errcode = '22023';
    end if;

    select p.*, c.name as category_name
      into v_product
      from public.products p
      left join public.categories c on c.id = p.category_id
     where p.id = v_line.product_id
     for update of p;

    if not found then
      raise exception 'That product no longer exists' using errcode = '23503';
    end if;

    if v_product.quantity_in_stock < v_line.quantity then
      raise exception 'Only % % of "%" left in stock, % requested',
        v_product.quantity_in_stock, v_product.unit, v_product.name, v_line.quantity
        using errcode = 'BS001';
    end if;

    v_line_total := round(v_product.sale_price_cents * v_line.quantity);
    v_line_cost  := round(v_product.cost_price_cents * v_line.quantity);

    insert into public.sale_items (
      sale_id, product_id, product_name, barcode, category_name, unit,
      unit_price_cents, unit_cost_cents, quantity,
      line_total_cents, line_cost_cents, line_profit_cents
    ) values (
      v_sale_id, v_product.id, v_product.name, v_product.barcode, v_product.category_name,
      v_product.unit, v_product.sale_price_cents, v_product.cost_price_cents, v_line.quantity,
      v_line_total, v_line_cost, v_line_total - v_line_cost
    );

    update public.products
       set quantity_in_stock = quantity_in_stock - v_line.quantity
     where id = v_product.id;

    insert into public.stock_movements (product_id, delta, reason, sale_id, created_by)
    values (v_product.id, -v_line.quantity, 'sale', v_sale_id, auth.uid());

    v_subtotal := v_subtotal + v_line_total;
    v_cost     := v_cost + v_line_cost;
    v_items    := v_items + v_line.quantity;
  end loop;

  v_discount_cents := case p_discount_type
    when 'percent' then round(v_subtotal * least(greatest(coalesce(p_discount_value, 0), 0), 100) / 100.0)
    when 'amount'  then round(greatest(coalesce(p_discount_value, 0), 0) * 100)
    else 0
  end;
  v_discount_cents := least(v_discount_cents, v_subtotal);

  v_total := v_subtotal - v_discount_cents;
  v_total_lbp := round((v_total / 100.0) * v_settings.usd_to_lbp_rate / v_settings.lbp_rounding)
                 * v_settings.lbp_rounding;

  update public.sales
     set subtotal_cents   = v_subtotal,
         discount_cents   = v_discount_cents,
         total_cents      = v_total,
         total_cost_cents = v_cost,
         profit_cents     = v_total - v_cost,
         item_count       = v_items,
         total_lbp        = v_total_lbp
   where id = v_sale_id;

  -- The takings go into the cash box, in the same transaction as the sale itself.
  if v_total > 0 then
    insert into public.cash_movements (kind, amount_cents, sale_id, note, created_by)
    values ('sale', v_total, v_sale_id, null, auth.uid());
  end if;

  return v_sale_id;
end;
$$;

revoke all on function public.checkout_sale(jsonb, text, numeric, text, text) from public, anon;
grant execute on function public.checkout_sale(jsonb, text, numeric, text, text) to authenticated;

-- ==========================================================================
-- 20260828090200_restock_cost.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- adjust_stock, now able to say what a delivery cost and who paid for it.
--
-- Two ways to fund one:
--
--   budget   the shop pays. One entry out of the cash box, and the balance drops.
--   outside  the owner pays from their own pocket. Two entries: the money coming in as an
--            investment, and the same amount going straight out to the supplier. The balance
--            is unchanged, which is the truth of it, and both halves stay visible so the
--            total put in from outside can be told apart from the takings.
--
-- Only a delivery costs money. Correcting a miscount moves the count without any cash
-- changing hands, so it never touches the ledger.
-- ---------------------------------------------------------------------------
create or replace function public.adjust_stock(
  p_product_id uuid,
  p_delta      numeric,
  p_reason     text default 'restock',
  p_note       text default null,
  p_cost_cents bigint default null,
  p_funding    text default 'budget'
) returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_product public.products%rowtype;
  v_new     numeric;
  v_cost    bigint;
begin
  if auth.uid() is null then
    raise exception 'You must be signed in to change stock' using errcode = '42501';
  end if;

  if p_reason not in ('restock', 'adjustment', 'initial') then
    raise exception 'Unknown stock reason %', p_reason using errcode = '22023';
  end if;

  if p_funding not in ('budget', 'outside') then
    raise exception 'Unknown funding source %', p_funding using errcode = '22023';
  end if;

  if p_delta is null or p_delta = 0 then
    raise exception 'Stock change must be a non-zero amount' using errcode = '22023';
  end if;

  select * into v_product from public.products where id = p_product_id for update;

  if not found then
    raise exception 'That product no longer exists' using errcode = '23503';
  end if;

  v_new := v_product.quantity_in_stock + p_delta;

  if v_new < 0 then
    raise exception 'That would leave "%" at % %, below zero',
      v_product.name, v_new, v_product.unit using errcode = 'BS001';
  end if;

  update public.products set quantity_in_stock = v_new where id = p_product_id;

  insert into public.stock_movements (product_id, delta, reason, note, created_by)
  values (p_product_id, p_delta, p_reason, nullif(btrim(coalesce(p_note, '')), ''), auth.uid());

  -- Left unsaid, a delivery is priced at what the article costs. Passing a figure overrides
  -- it, because a supplier's price on the day is what actually left the till.
  if p_reason = 'restock' and p_delta > 0 then
    v_cost := coalesce(p_cost_cents, round(v_product.cost_price_cents * p_delta));

    if v_cost < 0 then
      raise exception 'A delivery cannot cost less than nothing' using errcode = '22023';
    end if;

    if v_cost > 0 then
      if p_funding = 'outside' then
        insert into public.cash_movements
          (kind, amount_cents, product_id, product_name, note, created_by)
        values ('investment', v_cost, p_product_id, v_product.name,
                nullif(btrim(coalesce(p_note, '')), ''), auth.uid());
      end if;

      insert into public.cash_movements
        (kind, amount_cents, product_id, product_name, note, created_by)
      values ('restock', -v_cost, p_product_id, v_product.name,
              nullif(btrim(coalesce(p_note, '')), ''), auth.uid());
    end if;
  end if;

  return v_new;
end;
$$;

-- The four argument form is gone; anything still calling it would silently skip the cost.
drop function if exists public.adjust_stock(uuid, numeric, text, text);

revoke all on function public.adjust_stock(uuid, numeric, text, text, bigint, text) from public, anon;
grant execute on function public.adjust_stock(uuid, numeric, text, text, bigint, text) to authenticated;

-- ==========================================================================
-- 20260828090300_budget_reports.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- What is in the cash box, and how it got there.
-- ---------------------------------------------------------------------------
-- Dropped first rather than replaced. A later migration widens what this returns, and
-- CREATE OR REPLACE FUNCTION cannot change a return type, so replaying the whole schema
-- over an up-to-date database failed here.
drop function if exists public.report_budget();

create or replace function public.report_budget()
returns table (
  balance_cents        bigint,
  from_sales_cents     bigint,
  spent_restock_cents  bigint,
  invested_cents       bigint,
  entry_count          bigint
)
language sql
stable
as $$
  select
    coalesce(sum(amount_cents), 0)::bigint,
    coalesce(sum(amount_cents) filter (where kind = 'sale'), 0)::bigint,
    -- Stored negative; reported as the positive amount that was spent.
    coalesce(-sum(amount_cents) filter (where kind = 'restock'), 0)::bigint,
    coalesce(sum(amount_cents) filter (where kind = 'investment'), 0)::bigint,
    count(*)::bigint
  from public.cash_movements;
$$;

-- The ledger itself, newest first, so the balance can always be traced to its causes.
create or replace function public.list_cash_movements(p_limit integer default 100)
returns table (
  id           uuid,
  kind         text,
  amount_cents bigint,
  product_name text,
  note         text,
  created_at   timestamptz
)
language sql
stable
as $$
  select m.id, m.kind, m.amount_cents, m.product_name, m.note, m.created_at
  from public.cash_movements m
  order by m.created_at desc, m.id desc
  limit greatest(coalesce(p_limit, 100), 1);
$$;

do $$
declare fn text;
begin
  foreach fn in array array[
    'public.report_budget()',
    'public.list_cash_movements(integer)'
  ]
  loop
    execute format('revoke all on function %s from public, anon', fn);
    execute format('grant execute on function %s to authenticated', fn);
  end loop;
end;
$$;

-- ==========================================================================
-- 20260828090400_reset_shop.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- reset_shop: empties the whole thing.
--
-- Deliberately blunt and deliberately awkward to call. It takes the word RESET and refuses
-- anything else, so it cannot be reached by a stray tap or a mistyped request: whoever runs
-- it has to have meant it.
--
-- Everything goes. Sales, the stock ledger, the cash box, every article and every category.
-- What survives is the settings row, because the exchange rate is a fact about the country
-- rather than a fact about the shop, and losing it would just be an extra thing to type back in.
-- ---------------------------------------------------------------------------
create or replace function public.reset_shop(p_confirm text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_counts jsonb;
begin
  if auth.uid() is null then
    raise exception 'You must be signed in to reset the shop' using errcode = '42501';
  end if;

  if p_confirm is distinct from 'RESET' then
    raise exception 'Reset needs the word RESET to confirm it' using errcode = '22023';
  end if;

  -- Counted before the delete, so the app can say exactly what it removed.
  select jsonb_build_object(
    'sales',      (select count(*) from public.sales),
    'sale_items', (select count(*) from public.sale_items),
    'stock',      (select count(*) from public.stock_movements),
    'cash',       (select count(*) from public.cash_movements),
    'products',   (select count(*) from public.products),
    'categories', (select count(*) from public.categories)
  ) into v_counts;

  /*
    Every one of these carries `where true`, which looks redundant and is not.

    Supabase preloads the safeupdate extension, which refuses any DELETE or UPDATE without a
    WHERE clause so that a mistyped statement cannot empty a table. A plain Postgres does not,
    which is how this shipped passing every local test and then failed in the shop with
    "DELETE requires a WHERE clause". The guard is worth keeping; this really does mean to
    empty the table, so it says so out loud rather than by omission.

    Order matters only for stock_movements, whose sale_id is ON DELETE SET NULL rather than
    cascade; the rest fall away with their parents.
  */
  delete from public.cash_movements  where true;
  delete from public.stock_movements where true;
  delete from public.sale_items      where true;
  delete from public.sales           where true;
  delete from public.products        where true;
  delete from public.categories      where true;

  return v_counts;
end;
$$;

revoke all on function public.reset_shop(text) from public, anon;
grant execute on function public.reset_shop(text) to authenticated;

-- ==========================================================================
-- 20260830090000_ledger_kinds.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- The cash box learns four more ways money moves.
--
-- Until now the ledger knew about three things: a sale coming in, a delivery going out, and
-- the owner putting money in from their own pocket. Four more were happening in the shop
-- without leaving a trace:
--
--   opening      the first stock of a brand new article, which is a purchase like any other
--                and was previously written straight into the products table with no entry
--                at all, so the balance simply ignored it.
--   correction   a miscount found on the shelf. Stock that is there and was not on the books
--                was paid for by someone, so the balance has to come down to account for it;
--                stock that is missing was never really bought, so the balance goes back up.
--   void        a sale rung up in error and taken back out again.
--   refund      goods returned by a customer and paid back over the counter.
--
-- A correction is the one kind that can point either way, so the direction constraint is
-- written out per kind rather than as one rule with exceptions.
-- ---------------------------------------------------------------------------

alter table public.cash_movements
  drop constraint if exists cash_movements_kind_check;
alter table public.cash_movements
  add constraint cash_movements_kind_check check (
    kind in ('sale', 'restock', 'opening', 'investment', 'correction', 'void', 'refund')
  );

alter table public.cash_movements
  drop constraint if exists cash_direction;
alter table public.cash_movements
  add constraint cash_direction check (
    (kind = 'sale'       and amount_cents >= 0) or
    (kind = 'investment' and amount_cents >= 0) or
    (kind = 'restock'    and amount_cents <= 0) or
    (kind = 'opening'    and amount_cents <= 0) or
    (kind = 'void'       and amount_cents <= 0) or
    (kind = 'refund'     and amount_cents <= 0) or
    -- Found stock costs money, missing stock gives it back. Both are corrections.
    (kind = 'correction')
  );

-- ---------------------------------------------------------------------------
-- The stock ledger gains the two reasons that put units back on the shelf.
-- ---------------------------------------------------------------------------
alter table public.stock_movements
  drop constraint if exists stock_movements_reason_check;
alter table public.stock_movements
  add constraint stock_movements_reason_check check (
    reason in ('sale', 'restock', 'adjustment', 'initial', 'void', 'refund')
  );

-- ---------------------------------------------------------------------------
-- The balance, broken out far enough that every part of it can be pointed at.
--
-- Money that went out is reported as the positive amount that left, because "spent 40" reads
-- as what happened and "-40" reads as a figure someone has to interpret. Corrections keep
-- their sign, since which way they went is the whole point of them.
-- ---------------------------------------------------------------------------
drop function if exists public.report_budget();

create or replace function public.report_budget()
returns table (
  balance_cents        bigint,
  from_sales_cents     bigint,
  spent_restock_cents  bigint,
  spent_opening_cents  bigint,
  invested_cents       bigint,
  corrections_cents    bigint,
  refunded_cents       bigint,
  voided_cents         bigint,
  entry_count          bigint
)
language sql
stable
as $$
  select
    coalesce(sum(amount_cents), 0)::bigint,
    coalesce(sum(amount_cents) filter (where kind = 'sale'), 0)::bigint,
    coalesce(-sum(amount_cents) filter (where kind = 'restock'), 0)::bigint,
    coalesce(-sum(amount_cents) filter (where kind = 'opening'), 0)::bigint,
    coalesce(sum(amount_cents) filter (where kind = 'investment'), 0)::bigint,
    coalesce(sum(amount_cents) filter (where kind = 'correction'), 0)::bigint,
    coalesce(-sum(amount_cents) filter (where kind = 'refund'), 0)::bigint,
    coalesce(-sum(amount_cents) filter (where kind = 'void'), 0)::bigint,
    count(*)::bigint
  from public.cash_movements;
$$;

-- ---------------------------------------------------------------------------
-- What the shelves are worth.
--
-- The cash box says what there is to spend. This says what has already been spent and is
-- still sitting on the shelf waiting to be sold, which is the other half of knowing whether
-- the shop is doing well: a low balance with a full stockroom is a different situation
-- entirely from a low balance with nothing on the shelves.
-- ---------------------------------------------------------------------------
create or replace function public.report_inventory_value()
returns table (
  cost_value_cents   bigint,
  retail_value_cents bigint,
  article_count      bigint,
  unit_count         numeric
)
language sql
stable
as $$
  select
    coalesce(sum(round(p.cost_price_cents * p.quantity_in_stock)), 0)::bigint,
    coalesce(sum(round(p.sale_price_cents * p.quantity_in_stock)), 0)::bigint,
    count(*) filter (where p.quantity_in_stock > 0)::bigint,
    coalesce(sum(p.quantity_in_stock), 0)::numeric
  from public.products p
  where p.is_active;
$$;

do $$
declare fn text;
begin
  foreach fn in array array[
    'public.report_budget()',
    'public.report_inventory_value()'
  ]
  loop
    execute format('revoke all on function %s from public, anon', fn);
    execute format('grant execute on function %s to authenticated', fn);
  end loop;
end;
$$;

-- ==========================================================================
-- 20260830090100_cost_batches.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- What a thing cost, when the answer stopped being one number.
--
-- A supplier's price moves. Buy ten at $15, sell none, then buy ten more at $20 and the
-- shelf holds twenty units that did not cost the same as each other. There are two honest
-- answers to "what did this cost", and the shop picks which one it wants:
--
--   average   the twenty units are treated as costing $17.50 each. One number per article,
--             no questions at the till, and profit is right across the stock as a whole.
--
--   batch     the ten at $15 and the ten at $20 stay apart. Selling asks which of the two
--             is going over the counter, and profit is exact per unit. The question stops
--             asking itself the moment the older price sells out, because then there is
--             only one batch left and nothing to choose between.
--
-- Either way the batches are kept, so the two modes are the same bookkeeping read two ways
-- and switching between them is defined rather than destructive. The invariant that makes
-- that work: the remaining quantities across an article's batches always add up to exactly
-- its quantity_in_stock.
-- ---------------------------------------------------------------------------

alter table public.app_settings
  add column if not exists cost_method text not null default 'average';
alter table public.app_settings
  drop constraint if exists app_settings_cost_method_check;
alter table public.app_settings
  add constraint app_settings_cost_method_check check (cost_method in ('average', 'batch'));

-- The price the last delivery was actually charged at, kept beside the costing figure.
-- In average mode cost_price_cents is a blend and this is the real number the supplier said,
-- which is the one worth seeing when deciding what to charge.
alter table public.products
  add column if not exists last_cost_price_cents integer;

-- ---------------------------------------------------------------------------
-- stock_batches: units on the shelf, grouped by what they cost.
-- ---------------------------------------------------------------------------
create table if not exists public.stock_batches (
  id                 uuid          primary key default gen_random_uuid(),
  product_id         uuid          not null references public.products (id) on delete cascade,
  unit_cost_cents    integer       not null check (unit_cost_cents >= 0),
  quantity_received  numeric(12,3) not null check (quantity_received >= 0),
  quantity_remaining numeric(12,3) not null check (quantity_remaining >= 0),
  source             text          not null default 'restock'
                                   check (source in ('opening', 'restock', 'average', 'correction')),
  note               text,
  received_at        timestamptz   not null default now(),
  created_by         uuid          references auth.users (id) on delete set null,

  -- A batch can give back units it already handed out, when a sale is voided or returned,
  -- but it can never hold more than it took in.
  constraint stock_batches_within_received check (quantity_remaining <= quantity_received)
);

-- Oldest first is the order every allocation walks in, so it is the order the index keeps.
create index if not exists stock_batches_open_idx
  on public.stock_batches (product_id, received_at, id)
  where quantity_remaining > 0;

-- ---------------------------------------------------------------------------
-- product_price_history: every time a price moved, and what moved it.
-- ---------------------------------------------------------------------------
create table if not exists public.product_price_history (
  id                   uuid          primary key default gen_random_uuid(),
  product_id           uuid          not null references public.products (id) on delete cascade,
  changed_at           timestamptz   not null default now(),
  source               text          not null
                                     check (source in ('opening', 'restock', 'manual', 'method')),
  quantity             numeric(12,3),
  stock_before         numeric(12,3),
  stock_after          numeric(12,3),
  -- What this particular delivery was charged at, per unit. Null for a hand edit.
  purchase_cost_cents  integer,
  old_cost_cents       integer       not null,
  new_cost_cents       integer       not null,
  old_sale_price_cents integer       not null,
  new_sale_price_cents integer       not null,
  note                 text,
  created_by           uuid          references auth.users (id) on delete set null
);

create index if not exists product_price_history_idx
  on public.product_price_history (product_id, changed_at desc);

-- ---------------------------------------------------------------------------
-- Backfill: every article already holding stock gets the batch it should always have had.
--
-- Guarded on there being none, so this runs once however many times the schema is applied.
-- ---------------------------------------------------------------------------
insert into public.stock_batches
  (product_id, unit_cost_cents, quantity_received, quantity_remaining, source, note)
select p.id, p.cost_price_cents, p.quantity_in_stock, p.quantity_in_stock, 'opening',
       'Stock already on the shelf when batches were introduced'
from public.products p
where p.quantity_in_stock > 0
  and not exists (select 1 from public.stock_batches b where b.product_id = p.id);

-- ---------------------------------------------------------------------------
-- reconcile_batches: make the batches agree with the shelf.
--
-- quantity_in_stock is the figure the shop counts and trusts. The batches are a story about
-- where that figure came from, and a story can go missing: a row inserted straight into the
-- products table, an import, an article that predates any of this. Rather than refuse to
-- sell something that is visibly on the shelf, the gap is filled with a batch priced at what
-- the article says it costs, which is exactly how the whole system costed things before
-- batches existed.
--
-- The opposite drift is possible too, if stock is written down behind the ledger's back, and
-- is trimmed off the newest batches so the oldest prices survive to be sold at.
-- ---------------------------------------------------------------------------
create or replace function public.reconcile_batches(p_product_id uuid, p_expected numeric)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_have  numeric;
  v_cost  integer;
  v_over  numeric;
  v_batch record;
  v_drop  numeric;
begin
  if p_expected is null or p_expected < 0 then
    return;
  end if;

  select coalesce(sum(quantity_remaining), 0) into v_have
    from public.stock_batches
   where product_id = p_product_id and quantity_remaining > 0;

  if v_have = p_expected then
    return;
  end if;

  if v_have < p_expected then
    select cost_price_cents into v_cost from public.products where id = p_product_id;

    insert into public.stock_batches
      (product_id, unit_cost_cents, quantity_received, quantity_remaining, source, note)
    values (p_product_id, greatest(coalesce(v_cost, 0), 0),
            p_expected - v_have, p_expected - v_have, 'opening',
            'Stock on the shelf with no purchase behind it');
    return;
  end if;

  -- More in the batches than on the shelf. Newest first, so the oldest prices are the ones
  -- left standing to be sold at.
  v_over := v_have - p_expected;

  for v_batch in
    select * from public.stock_batches
     where product_id = p_product_id and quantity_remaining > 0
     order by received_at desc, id desc
     for update
  loop
    exit when v_over <= 0;

    v_drop := least(v_batch.quantity_remaining, v_over);
    update public.stock_batches
       set quantity_remaining = quantity_remaining - v_drop
     where id = v_batch.id;
    v_over := v_over - v_drop;
  end loop;
end;
$$;

-- ---------------------------------------------------------------------------
-- consume_batches: take a quantity off the shelf and say what it cost.
--
-- A preferred batch is honoured first, which is the till answering "the older ones". Once
-- that batch is exhausted the rest comes from the oldest remaining, so a line that spans two
-- prices is priced across both rather than refused.
--
-- Returns the allocation it made, which the caller stores: it is the only way a void or a
-- refund can later put the units back where they came from.
-- ---------------------------------------------------------------------------
create or replace function public.consume_batches(
  p_product_id uuid,
  p_quantity   numeric,
  p_batch_id   uuid default null
) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_left  numeric := p_quantity;
  v_take  numeric;
  v_batch record;
  v_out   jsonb := '[]'::jsonb;
begin
  if p_quantity is null or p_quantity <= 0 then
    return v_out;
  end if;

  for v_batch in
    select * from public.stock_batches
     where product_id = p_product_id
       and quantity_remaining > 0
     -- The chosen batch first, everything else oldest first.
     order by (id is distinct from p_batch_id), received_at, id
     for update
  loop
    exit when v_left <= 0;

    v_take := least(v_batch.quantity_remaining, v_left);

    update public.stock_batches
       set quantity_remaining = quantity_remaining - v_take
     where id = v_batch.id;

    v_out := v_out || jsonb_build_object(
      'batch_id', v_batch.id,
      'quantity', v_take,
      'unit_cost_cents', v_batch.unit_cost_cents
    );
    v_left := v_left - v_take;
  end loop;

  if v_left > 0 then
    -- The batches and the stock count disagreeing is a bug, not a shop problem, so it says
    -- so plainly rather than quietly selling units that are not accounted for.
    raise exception 'Stock records for this article do not add up: % units unaccounted for', v_left
      using errcode = 'BS002';
  end if;

  return v_out;
end;
$$;

-- ---------------------------------------------------------------------------
-- return_to_batches: the reverse, used by voids and refunds.
--
-- Units go back to the batch they left, so an article sold at the old price and handed back
-- is once again stock at the old price rather than silently repriced.
-- ---------------------------------------------------------------------------
create or replace function public.return_to_batches(p_allocations jsonb)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_line record;
begin
  if p_allocations is null or jsonb_typeof(p_allocations) <> 'array' then
    return;
  end if;

  for v_line in
    select (elem ->> 'batch_id')::uuid as batch_id,
           sum((elem ->> 'quantity')::numeric) as quantity
    from jsonb_array_elements(p_allocations) as elem
    group by 1
    order by 1
  loop
    update public.stock_batches
       set quantity_remaining = least(quantity_received, quantity_remaining + v_line.quantity)
     where id = v_line.batch_id;
  end loop;
end;
$$;

-- ---------------------------------------------------------------------------
-- collapse_to_average: fold every open batch of an article into one.
--
-- This is what average mode means in practice. The weighted average is taken over what is
-- still on the shelf, not over everything ever bought, because the question being answered
-- is "what did the stock I am holding cost me".
--
-- Returns the resulting unit cost, or null when there is nothing left to average.
-- ---------------------------------------------------------------------------
create or replace function public.collapse_to_average(p_product_id uuid)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_qty  numeric;
  v_cost numeric;
  v_unit integer;
begin
  select coalesce(sum(quantity_remaining), 0),
         coalesce(sum(quantity_remaining * unit_cost_cents), 0)
    into v_qty, v_cost
    from public.stock_batches
   where product_id = p_product_id
     and quantity_remaining > 0;

  -- Spent batches are history and are kept; only the open ones are being merged. The delete
  -- below takes the locks; an aggregate cannot carry FOR UPDATE of its own.
  delete from public.stock_batches
   where product_id = p_product_id and quantity_remaining > 0;

  if v_qty <= 0 then
    return null;
  end if;

  v_unit := round(v_cost / v_qty);

  insert into public.stock_batches
    (product_id, unit_cost_cents, quantity_received, quantity_remaining, source, note)
  values (p_product_id, v_unit, v_qty, v_qty, 'average', 'Averaged across the stock on hand');

  return v_unit;
end;
$$;

-- ---------------------------------------------------------------------------
-- set_cost_method: switching how the shop counts cost.
--
-- Going to average folds every article's open batches into one at its weighted average, so
-- the till stops asking and the cost on each article becomes that blend. Going the other way
-- changes nothing that exists: the single batch each article holds is simply where the next
-- delivery starts appending beside rather than merging into.
-- ---------------------------------------------------------------------------
create or replace function public.set_cost_method(p_method text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_product record;
  v_unit    integer;
begin
  if auth.uid() is null then
    raise exception 'You must be signed in to change how cost is counted' using errcode = '42501';
  end if;

  if p_method not in ('average', 'batch') then
    raise exception 'Unknown cost method %', p_method using errcode = '22023';
  end if;

  update public.app_settings set cost_method = p_method where id = 1;

  if p_method = 'average' then
    for v_product in select id, cost_price_cents, sale_price_cents from public.products loop
      v_unit := public.collapse_to_average(v_product.id);

      if v_unit is not null and v_unit is distinct from v_product.cost_price_cents then
        update public.products set cost_price_cents = v_unit where id = v_product.id;

        insert into public.product_price_history (
          product_id, source, old_cost_cents, new_cost_cents,
          old_sale_price_cents, new_sale_price_cents, note, created_by
        ) values (
          v_product.id, 'method', v_product.cost_price_cents, v_unit,
          v_product.sale_price_cents, v_product.sale_price_cents,
          'Switched to average cost', auth.uid()
        );
      end if;
    end loop;
  end if;

  return p_method;
end;
$$;

do $$
declare fn text;
begin
  foreach fn in array array[
    'public.reconcile_batches(uuid, numeric)',
    'public.consume_batches(uuid, numeric, uuid)',
    'public.return_to_batches(jsonb)',
    'public.collapse_to_average(uuid)',
    'public.set_cost_method(text)'
  ]
  loop
    execute format('revoke all on function %s from public, anon', fn);
  end loop;
end;
$$;

-- Only set_cost_method is called from a screen. The three helpers are internal plumbing for
-- checkout_sale and adjust_stock, and stay unreachable from any device.
grant execute on function public.set_cost_method(text) to authenticated;

-- ==========================================================================
-- 20260830090200_adjust_stock.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- adjust_stock, rewritten around the price the supplier actually charged.
--
-- Three things changed.
--
-- First, a delivery is now priced per unit rather than as a lump sum. "Twelve arrived at
-- $1.75 each" is what the invoice says and what the shop knows; the total is arithmetic and
-- the app can do that itself. It also makes the interesting question askable: is $1.75 what
-- this cost last time?
--
-- Second, a delivery lands as a batch. In average mode the batches are folded together
-- immediately and the article carries the blend. In batch mode they stay apart until the
-- older stock sells out. Either way the article's cost_price_cents ends up as the weighted
-- average of what is on the shelf, so every valuation and margin figure in the system keeps
-- meaning the same thing.
--
-- Third, correcting a miscount now moves money, which it always should have. Stock that is
-- on the shelf but not on the books was paid for out of someone's pocket, so the balance
-- comes down by what it is worth. Stock that is on the books but not on the shelf was never
-- really bought, so the balance goes back up. Neither is a purchase, so both are recorded as
-- corrections rather than hidden inside the delivery figures.
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- The article's cost, restated from the batches behind it.
--
-- Called after anything that changes what is on the shelf. Leaves the cost alone when the
-- shelf is empty: the last price paid is a better guess for the next delivery than zero is.
-- ---------------------------------------------------------------------------
create or replace function public.sync_cost_from_batches(p_product_id uuid)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_qty  numeric;
  v_cost numeric;
  v_unit integer;
begin
  select coalesce(sum(quantity_remaining), 0),
         coalesce(sum(quantity_remaining * unit_cost_cents), 0)
    into v_qty, v_cost
    from public.stock_batches
   where product_id = p_product_id
     and quantity_remaining > 0;

  if v_qty <= 0 then
    return null;
  end if;

  v_unit := round(v_cost / v_qty);
  update public.products set cost_price_cents = v_unit where id = p_product_id;
  return v_unit;
end;
$$;

drop function if exists public.adjust_stock(uuid, numeric, text, text);
drop function if exists public.adjust_stock(uuid, numeric, text, text, bigint, text);
drop function if exists public.adjust_stock(uuid, numeric, text, text, integer, text, integer);

create or replace function public.adjust_stock(
  p_product_id           uuid,
  p_delta                numeric,
  p_reason               text    default 'restock',
  p_note                 text    default null,
  -- What one unit of this delivery cost. Left null, the article's current cost stands, which
  -- is the right answer whenever the supplier charged what they usually do.
  p_unit_cost_cents      integer default null,
  p_funding              text    default 'budget',
  -- A new shelf price to go with the new cost. Null leaves the price where it is.
  p_new_sale_price_cents integer default null
) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_product   public.products%rowtype;
  v_settings  public.app_settings%rowtype;
  v_new       numeric;
  v_unit      integer;
  v_total     bigint;
  v_kind      text;
  v_cost_now  integer;
  v_alloc     jsonb;
  v_taken     numeric;
  v_taken_val numeric;
  v_sale      integer;
  v_prev_cost integer;
  v_prev_sale integer;
begin
  if auth.uid() is null then
    raise exception 'You must be signed in to change stock' using errcode = '42501';
  end if;

  if p_reason not in ('restock', 'adjustment', 'initial') then
    raise exception 'Unknown stock reason %', p_reason using errcode = '22023';
  end if;

  if p_funding not in ('budget', 'outside') then
    raise exception 'Unknown funding source %', p_funding using errcode = '22023';
  end if;

  if p_delta is null or p_delta = 0 then
    raise exception 'Stock change must be a non-zero amount' using errcode = '22023';
  end if;

  if p_unit_cost_cents is not null and p_unit_cost_cents < 0 then
    raise exception 'A price cannot be less than nothing' using errcode = '22023';
  end if;

  if p_new_sale_price_cents is not null and p_new_sale_price_cents < 0 then
    raise exception 'A price cannot be less than nothing' using errcode = '22023';
  end if;

  select * into v_settings from public.app_settings where id = 1;
  select * into v_product from public.products where id = p_product_id for update;

  if not found then
    raise exception 'That product no longer exists' using errcode = '23503';
  end if;

  -- The batches are brought level with the shelf before anything moves, so every figure
  -- below is drawn from a complete picture rather than a partial one.
  perform public.reconcile_batches(p_product_id, v_product.quantity_in_stock);

  -- Held from before anything moves, so the caller can be told what changed rather than
  -- being handed the new figures and left to guess whether they are new.
  v_prev_cost := v_product.cost_price_cents;
  v_prev_sale := v_product.sale_price_cents;

  v_new := v_product.quantity_in_stock + p_delta;

  if v_new < 0 then
    raise exception 'That would leave "%" at % %, below zero',
      v_product.name, v_new, v_product.unit using errcode = 'BS001';
  end if;

  update public.products set quantity_in_stock = v_new where id = p_product_id;

  insert into public.stock_movements (product_id, delta, reason, note, created_by)
  values (p_product_id, p_delta, p_reason, nullif(btrim(coalesce(p_note, '')), ''), auth.uid());

  v_sale := v_product.sale_price_cents;

  -- ---------------------------------------------------------------------------
  -- A delivery, or the first stock of a new article. Both are a purchase.
  -- ---------------------------------------------------------------------------
  if p_reason in ('restock', 'initial') and p_delta > 0 then
    v_unit  := coalesce(p_unit_cost_cents, v_product.cost_price_cents);
    v_total := round(v_unit::numeric * p_delta);
    v_kind  := case when p_reason = 'initial' then 'opening' else 'restock' end;

    insert into public.stock_batches
      (product_id, unit_cost_cents, quantity_received, quantity_remaining, source, note, created_by)
    values (p_product_id, v_unit, p_delta, p_delta,
            case when p_reason = 'initial' then 'opening' else 'restock' end,
            nullif(btrim(coalesce(p_note, '')), ''), auth.uid());

    -- Average mode folds the shelf back down to one price straight away; batch mode leaves
    -- the new delivery standing beside what was already there.
    if v_settings.cost_method = 'average' then
      perform public.collapse_to_average(p_product_id);
    end if;

    v_cost_now := coalesce(public.sync_cost_from_batches(p_product_id), v_unit);

    update public.products
       set last_cost_price_cents = v_unit,
           sale_price_cents = coalesce(p_new_sale_price_cents, sale_price_cents)
     where id = p_product_id;

    v_sale := coalesce(p_new_sale_price_cents, v_product.sale_price_cents);

    -- Worth a history row only when something actually moved.
    if v_cost_now is distinct from v_product.cost_price_cents
       or v_sale is distinct from v_product.sale_price_cents
       or v_unit is distinct from v_product.cost_price_cents then
      insert into public.product_price_history (
        product_id, source, quantity, stock_before, stock_after, purchase_cost_cents,
        old_cost_cents, new_cost_cents, old_sale_price_cents, new_sale_price_cents,
        note, created_by
      ) values (
        p_product_id,
        case when p_reason = 'initial' then 'opening' else 'restock' end,
        p_delta, v_product.quantity_in_stock, v_new, v_unit,
        v_product.cost_price_cents, v_cost_now,
        v_product.sale_price_cents, v_sale,
        nullif(btrim(coalesce(p_note, '')), ''), auth.uid()
      );
    end if;

    if v_total > 0 then
      -- Paid from outside, the money comes in and goes straight back out, so the balance is
      -- unchanged and both halves stay visible.
      if p_funding = 'outside' then
        insert into public.cash_movements
          (kind, amount_cents, product_id, product_name, note, created_by)
        values ('investment', v_total, p_product_id, v_product.name,
                nullif(btrim(coalesce(p_note, '')), ''), auth.uid());
      end if;

      insert into public.cash_movements
        (kind, amount_cents, product_id, product_name, note, created_by)
      values (v_kind, -v_total, p_product_id, v_product.name,
              nullif(btrim(coalesce(p_note, '')), ''), auth.uid());
    end if;

  -- ---------------------------------------------------------------------------
  -- A correction. No goods changed hands, but the books were wrong about money.
  -- ---------------------------------------------------------------------------
  elsif p_reason = 'adjustment' then
    if p_delta > 0 then
      -- Found on the shelf. Valued at what the article costs, unless a price was given.
      v_unit := coalesce(p_unit_cost_cents, v_product.cost_price_cents);

      insert into public.stock_batches
        (product_id, unit_cost_cents, quantity_received, quantity_remaining, source, note, created_by)
      values (p_product_id, v_unit, p_delta, p_delta, 'correction',
              nullif(btrim(coalesce(p_note, '')), ''), auth.uid());

      if v_settings.cost_method = 'average' then
        perform public.collapse_to_average(p_product_id);
      end if;

      v_total := round(v_unit::numeric * p_delta);
    else
      -- Missing from the shelf. Valued at what those particular units cost, taken from the
      -- oldest batches, so the figure matches the stock that has actually gone.
      v_alloc := public.consume_batches(p_product_id, -p_delta);

      select coalesce(sum((elem ->> 'quantity')::numeric), 0),
             coalesce(sum((elem ->> 'quantity')::numeric
                          * (elem ->> 'unit_cost_cents')::numeric), 0)
        into v_taken, v_taken_val
        from jsonb_array_elements(v_alloc) as elem;

      v_total := -round(v_taken_val);
    end if;

    perform public.sync_cost_from_batches(p_product_id);

    if v_total <> 0 then
      insert into public.cash_movements
        (kind, amount_cents, product_id, product_name, note, created_by)
      values ('correction', -v_total, p_product_id, v_product.name,
              nullif(btrim(coalesce(p_note, '')), ''), auth.uid());
    end if;

  -- ---------------------------------------------------------------------------
  -- A delivery entered as a negative, which is a return to the supplier. Stock leaves and
  -- the money comes back, priced at what those units cost.
  -- ---------------------------------------------------------------------------
  elsif p_delta < 0 then
    v_alloc := public.consume_batches(p_product_id, -p_delta);

    select coalesce(sum((elem ->> 'quantity')::numeric
                        * (elem ->> 'unit_cost_cents')::numeric), 0)
      into v_taken_val
      from jsonb_array_elements(v_alloc) as elem;

    perform public.sync_cost_from_batches(p_product_id);

    if v_taken_val > 0 then
      insert into public.cash_movements
        (kind, amount_cents, product_id, product_name, note, created_by)
      values ('correction', round(v_taken_val), p_product_id, v_product.name,
              nullif(btrim(coalesce(p_note, '')), ''), auth.uid());
    end if;
  end if;

  select * into v_product from public.products where id = p_product_id;

  return jsonb_build_object(
    'stock',                v_new,
    'cost_price_cents',     v_product.cost_price_cents,
    'previous_cost_cents',  v_prev_cost,
    'sale_price_cents',     v_product.sale_price_cents,
    'previous_sale_cents',  v_prev_sale,
    'last_cost_cents',      v_product.last_cost_price_cents,
    'cost_changed',         (v_product.cost_price_cents is distinct from v_prev_cost),
    'sale_price_changed',   (v_product.sale_price_cents is distinct from v_prev_sale)
  );
end;
$$;

revoke all on function public.sync_cost_from_batches(uuid) from public, anon;
revoke all on function public.adjust_stock(uuid, numeric, text, text, integer, text, integer)
  from public, anon;
grant execute on function public.adjust_stock(uuid, numeric, text, text, integer, text, integer)
  to authenticated;

-- ==========================================================================
-- 20260830090300_checkout_batches.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- checkout_sale, now taking the units off a particular batch.
--
-- The basket may name a batch per line. In average mode nothing ever does, and the sale
-- draws from the single batch the article has; in batch mode the till asks which price is
-- going over the counter and passes the answer through. A named batch that cannot cover the
-- line is topped up from the oldest remaining rather than refused, because the customer is
-- standing there and the totals come out right either way.
--
-- What each line cost is no longer read off the article. It is the sum of what those exact
-- units cost when they were bought, which is the entire point of keeping batches: sell the
-- ten you paid $15 for and the profit says $15, whatever the next delivery charged.
--
-- The allocation is written to sale_item_batches, and that record is what later lets a void
-- or a refund put the units back on the batch they left rather than repricing them by
-- accident.
-- ---------------------------------------------------------------------------

create table if not exists public.sale_item_batches (
  id              uuid          primary key default gen_random_uuid(),
  sale_item_id    uuid          not null references public.sale_items (id) on delete cascade,
  -- The batch may be collapsed away later by a switch to average mode, so this goes null
  -- rather than taking the history with it. The quantity and cost stay either way.
  batch_id        uuid          references public.stock_batches (id) on delete set null,
  quantity        numeric(12,3) not null check (quantity > 0),
  unit_cost_cents integer       not null check (unit_cost_cents >= 0),
  created_at      timestamptz   not null default now()
);

create index if not exists sale_item_batches_item_idx
  on public.sale_item_batches (sale_item_id);

create or replace function public.checkout_sale(
  p_items            jsonb,
  p_discount_type    text default 'none',
  p_discount_value   numeric default 0,
  p_payment_currency text default 'USD',
  p_note             text default null
) returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_sale_id        uuid := gen_random_uuid();
  v_settings       public.app_settings%rowtype;
  v_line           record;
  v_product        record;
  v_subtotal       bigint := 0;
  v_cost           bigint := 0;
  v_items          numeric := 0;
  v_line_total     bigint;
  v_line_cost      bigint;
  v_discount_cents bigint := 0;
  v_total          bigint;
  v_total_lbp      numeric;
  v_item_id        uuid;
  v_alloc          jsonb;
begin
  if auth.uid() is null then
    raise exception 'You must be signed in to take a sale' using errcode = '42501';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Cannot check out an empty cart' using errcode = '22023';
  end if;

  if p_discount_type not in ('none', 'percent', 'amount') then
    raise exception 'Unknown discount type %', p_discount_type using errcode = '22023';
  end if;

  if p_payment_currency not in ('USD', 'LBP') then
    raise exception 'Unknown payment currency %', p_payment_currency using errcode = '22023';
  end if;

  select * into v_settings from public.app_settings where id = 1;

  insert into public.sales (id, payment_currency, discount_type, discount_value, note,
                            usd_to_lbp_rate, created_by)
  values (v_sale_id, p_payment_currency, p_discount_type, greatest(coalesce(p_discount_value, 0), 0),
          nullif(btrim(coalesce(p_note, '')), ''), v_settings.usd_to_lbp_rate, auth.uid());

  -- Folded on the article and the batch together. Scanning the same item twice still makes
  -- one line, but the same article taken from two different prices makes two, which is the
  -- truth of what left the shelf.
  for v_line in
    select (elem ->> 'product_id')::uuid as product_id,
           (elem ->> 'batch_id')::uuid   as batch_id,
           sum((elem ->> 'quantity')::numeric) as quantity
    from jsonb_array_elements(p_items) as elem
    group by 1, 2
    order by 1, 2
  loop
    if v_line.quantity is null or v_line.quantity <= 0 then
      raise exception 'Quantity must be greater than zero' using errcode = '22023';
    end if;

    select p.*, c.name as category_name
      into v_product
      from public.products p
      left join public.categories c on c.id = p.category_id
     where p.id = v_line.product_id
     for update of p;

    if not found then
      raise exception 'That product no longer exists' using errcode = '23503';
    end if;

    if v_product.quantity_in_stock < v_line.quantity then
      raise exception 'Only % % of "%" left in stock, % requested',
        v_product.quantity_in_stock, v_product.unit, v_product.name, v_line.quantity
        using errcode = 'BS001';
    end if;

    -- An article that has never been through a delivery has stock but no batches behind it,
    -- and the till is the wrong place to discover that. Levelled up first, priced at what
    -- the article says it costs.
    perform public.reconcile_batches(v_line.product_id, v_product.quantity_in_stock);

    -- Take the units first: what they cost is an answer, not an assumption.
    v_alloc := public.consume_batches(v_line.product_id, v_line.quantity, v_line.batch_id);

    select coalesce(round(sum((elem ->> 'quantity')::numeric
                              * (elem ->> 'unit_cost_cents')::numeric)), 0)
      into v_line_cost
      from jsonb_array_elements(v_alloc) as elem;

    v_line_total := round(v_product.sale_price_cents * v_line.quantity);

    insert into public.sale_items (
      sale_id, product_id, product_name, barcode, category_name, unit,
      unit_price_cents, unit_cost_cents, quantity,
      line_total_cents, line_cost_cents, line_profit_cents
    ) values (
      v_sale_id, v_product.id, v_product.name, v_product.barcode, v_product.category_name,
      v_product.unit, v_product.sale_price_cents, round(v_line_cost / v_line.quantity),
      v_line.quantity, v_line_total, v_line_cost, v_line_total - v_line_cost
    )
    returning id into v_item_id;

    insert into public.sale_item_batches (sale_item_id, batch_id, quantity, unit_cost_cents)
    select v_item_id,
           (elem ->> 'batch_id')::uuid,
           (elem ->> 'quantity')::numeric,
           (elem ->> 'unit_cost_cents')::integer
    from jsonb_array_elements(v_alloc) as elem;

    update public.products
       set quantity_in_stock = quantity_in_stock - v_line.quantity
     where id = v_product.id;

    -- Selling the last of an old batch changes what the shelf is worth, so the article's
    -- cost is restated from what is left rather than left standing at yesterday's blend.
    perform public.sync_cost_from_batches(v_product.id);

    insert into public.stock_movements (product_id, delta, reason, sale_id, created_by)
    values (v_product.id, -v_line.quantity, 'sale', v_sale_id, auth.uid());

    v_subtotal := v_subtotal + v_line_total;
    v_cost     := v_cost + v_line_cost;
    v_items    := v_items + v_line.quantity;
  end loop;

  v_discount_cents := case p_discount_type
    when 'percent' then round(v_subtotal * least(greatest(coalesce(p_discount_value, 0), 0), 100) / 100.0)
    when 'amount'  then round(greatest(coalesce(p_discount_value, 0), 0) * 100)
    else 0
  end;
  v_discount_cents := least(v_discount_cents, v_subtotal);

  v_total := v_subtotal - v_discount_cents;
  v_total_lbp := round((v_total / 100.0) * v_settings.usd_to_lbp_rate / v_settings.lbp_rounding)
                 * v_settings.lbp_rounding;

  update public.sales
     set subtotal_cents   = v_subtotal,
         discount_cents   = v_discount_cents,
         total_cents      = v_total,
         total_cost_cents = v_cost,
         profit_cents     = v_total - v_cost,
         item_count       = v_items,
         total_lbp        = v_total_lbp
   where id = v_sale_id;

  if v_total > 0 then
    insert into public.cash_movements (kind, amount_cents, sale_id, note, created_by)
    values ('sale', v_total, v_sale_id, null, auth.uid());
  end if;

  return v_sale_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- What is on the shelf, priced. The till reads this to know whether it has to ask.
--
-- One row back means one price and no question. Two or more means the article is holding
-- stock bought at different prices, and which one is going over the counter is a fact only
-- the person at the counter knows.
-- ---------------------------------------------------------------------------
create or replace function public.list_stock_batches(p_product_id uuid)
returns table (
  id                 uuid,
  unit_cost_cents    integer,
  quantity_remaining numeric,
  quantity_received  numeric,
  source             text,
  note               text,
  received_at        timestamptz
)
language sql
stable
as $$
  select b.id, b.unit_cost_cents, b.quantity_remaining, b.quantity_received,
         b.source, b.note, b.received_at
  from public.stock_batches b
  where b.product_id = p_product_id
    and b.quantity_remaining > 0
  order by b.received_at, b.id;
$$;

-- The price trail for one article, newest first.
create or replace function public.list_price_history(p_product_id uuid, p_limit integer default 50)
returns table (
  id                   uuid,
  changed_at           timestamptz,
  source               text,
  quantity             numeric,
  purchase_cost_cents  integer,
  old_cost_cents       integer,
  new_cost_cents       integer,
  old_sale_price_cents integer,
  new_sale_price_cents integer,
  note                 text
)
language sql
stable
as $$
  select h.id, h.changed_at, h.source, h.quantity, h.purchase_cost_cents,
         h.old_cost_cents, h.new_cost_cents, h.old_sale_price_cents, h.new_sale_price_cents,
         h.note
  from public.product_price_history h
  where h.product_id = p_product_id
  order by h.changed_at desc, h.id desc
  limit greatest(coalesce(p_limit, 50), 1);
$$;

do $$
declare fn text;
begin
  foreach fn in array array[
    'public.list_stock_batches(uuid)',
    'public.list_price_history(uuid, integer)'
  ]
  loop
    execute format('revoke all on function %s from public, anon', fn);
    execute format('grant execute on function %s to authenticated', fn);
  end loop;
end;
$$;

revoke all on function public.checkout_sale(jsonb, text, numeric, text, text) from public, anon;
grant execute on function public.checkout_sale(jsonb, text, numeric, text, text) to authenticated;

-- ==========================================================================
-- 20260830090400_create_product.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- create_product: adding an article is a purchase, and the books should say so.
--
-- Until now the first stock of a new article went in as a plain column value. Nothing
-- recorded that the shop had just spent money on a box of something, so the balance carried
-- on as though the shelf had filled itself. Ten articles entered at $30 each is $300 that
-- left someone's pocket and appeared nowhere.
--
-- So it asks the same question the delivery sheet already asks: shop money, or your own.
-- Shop money takes it out of the balance. Your own money is recorded as put in from outside
-- and the balance is left where it was, which is the truth of it, and the two stay
-- distinguishable so "what have I sunk into this place" remains an answerable question.
--
-- The insert and the opening stock happen in one transaction, so an article can never exist
-- holding stock nobody paid for.
-- ---------------------------------------------------------------------------
create or replace function public.create_product(
  p_barcode             text,
  p_name                text,
  p_category_id         uuid,
  p_cost_price_cents    integer,
  p_sale_price_cents    integer,
  p_quantity            numeric,
  p_low_stock_threshold numeric,
  p_unit                text,
  p_notes               text,
  p_funding             text default 'budget'
) returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id uuid;
begin
  if auth.uid() is null then
    raise exception 'You must be signed in to add an article' using errcode = '42501';
  end if;

  if p_funding not in ('budget', 'outside') then
    raise exception 'Unknown funding source %', p_funding using errcode = '22023';
  end if;

  if length(btrim(coalesce(p_name, ''))) = 0 then
    raise exception 'Give the article a name' using errcode = '22023';
  end if;

  if coalesce(p_quantity, 0) < 0 then
    raise exception 'Opening stock cannot be less than nothing' using errcode = '22023';
  end if;

  -- The shelf starts empty and is filled by adjust_stock below, so the opening stock leaves
  -- the same ledger trail every later delivery does.
  insert into public.products (
    barcode, name, category_id, cost_price_cents, sale_price_cents,
    quantity_in_stock, low_stock_threshold, unit, notes, last_cost_price_cents
  ) values (
    nullif(btrim(coalesce(p_barcode, '')), ''),
    btrim(p_name),
    p_category_id,
    greatest(coalesce(p_cost_price_cents, 0), 0),
    greatest(coalesce(p_sale_price_cents, 0), 0),
    0,
    greatest(coalesce(p_low_stock_threshold, 0), 0),
    coalesce(nullif(btrim(coalesce(p_unit, '')), ''), 'piece'),
    nullif(btrim(coalesce(p_notes, '')), ''),
    case when coalesce(p_quantity, 0) > 0 then greatest(coalesce(p_cost_price_cents, 0), 0) end
  )
  returning id into v_id;

  -- Where the article started, so the price trail has a beginning rather than appearing to
  -- spring into existence at the first delivery.
  insert into public.product_price_history (
    product_id, source, quantity, stock_before, stock_after, purchase_cost_cents,
    old_cost_cents, new_cost_cents, old_sale_price_cents, new_sale_price_cents,
    note, created_by
  ) values (
    v_id, 'opening', coalesce(p_quantity, 0), 0, coalesce(p_quantity, 0),
    greatest(coalesce(p_cost_price_cents, 0), 0),
    greatest(coalesce(p_cost_price_cents, 0), 0), greatest(coalesce(p_cost_price_cents, 0), 0),
    greatest(coalesce(p_sale_price_cents, 0), 0), greatest(coalesce(p_sale_price_cents, 0), 0),
    'Article added', auth.uid()
  );

  if coalesce(p_quantity, 0) > 0 then
    perform public.adjust_stock(
      v_id,
      p_quantity,
      'initial',
      'Opening stock',
      greatest(coalesce(p_cost_price_cents, 0), 0),
      p_funding,
      null
    );
  end if;

  return v_id;
end;
$$;

revoke all on function public.create_product(
  text, text, uuid, integer, integer, numeric, numeric, text, text, text
) from public, anon;
grant execute on function public.create_product(
  text, text, uuid, integer, integer, numeric, numeric, text, text, text
) to authenticated;

-- ==========================================================================
-- 20260830090500_void_refund.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- Taking a sale back, two different ways.
--
-- A void says the sale should never have happened: the wrong article was scanned, or the
-- customer changed their mind before leaving. It is a mistake being erased, so it is erased
-- everywhere, including from the day it was rung up on. Last Tuesday's report stops counting
-- it because last Tuesday it did not really happen.
--
-- A refund says the sale did happen and some of it is coming back now. That is a real event
-- with its own date, so it counts against today rather than reaching back into a month that
-- has already been read and acted on. It can be partial: three of the six tins are returned
-- and the other three stay sold.
--
-- Both put units back on the batch they came from, so stock handed back at last month's
-- price is still stock at last month's price, and both move the money in the same
-- transaction as the stock, so the shelf and the cash box can never disagree.
-- ---------------------------------------------------------------------------

alter table public.sales add column if not exists voided_at   timestamptz;
alter table public.sales add column if not exists voided_by   uuid references auth.users (id) on delete set null;
alter table public.sales add column if not exists void_reason text;

-- Every report walks live sales in date order, and after this most of them carry the filter.
create index if not exists sales_live_idx
  on public.sales (sold_at desc) where voided_at is null;

-- ---------------------------------------------------------------------------
-- sale_refunds: one counter transaction, with the lines that came back.
-- ---------------------------------------------------------------------------
create table if not exists public.sale_refunds (
  id           uuid          primary key default gen_random_uuid(),
  sale_id      uuid          not null references public.sales (id) on delete cascade,
  refunded_at  timestamptz   not null default now(),
  total_cents  bigint        not null default 0,
  cost_cents   bigint        not null default 0,
  profit_cents bigint        not null default 0,
  item_count   numeric(12,3) not null default 0,
  reason       text,
  created_by   uuid          references auth.users (id) on delete set null,
  created_at   timestamptz   not null default now()
);

create index if not exists sale_refunds_sale_idx on public.sale_refunds (sale_id);
create index if not exists sale_refunds_at_idx   on public.sale_refunds (refunded_at desc);

create table if not exists public.sale_refund_items (
  id               uuid          primary key default gen_random_uuid(),
  refund_id        uuid          not null references public.sale_refunds (id) on delete cascade,
  sale_item_id     uuid          not null references public.sale_items (id) on delete cascade,
  product_id       uuid          references public.products (id) on delete set null,
  product_name     text          not null,
  barcode          text,
  category_name    text,
  unit             text          not null default 'piece',
  quantity         numeric(12,3) not null check (quantity > 0),
  unit_price_cents integer       not null,
  unit_cost_cents  integer       not null,
  gross_cents      bigint        not null,
  -- What the customer actually gets back: the line less its share of the basket discount,
  -- the same proportional split the reports use, so a refund can never hand back more than
  -- was taken.
  net_cents        bigint        not null,
  cost_cents       bigint        not null,
  created_at       timestamptz   not null default now()
);

create index if not exists sale_refund_items_refund_idx on public.sale_refund_items (refund_id);
create index if not exists sale_refund_items_item_idx   on public.sale_refund_items (sale_item_id);

-- ---------------------------------------------------------------------------
-- How many of a sold line have already gone back.
-- ---------------------------------------------------------------------------
create or replace function public.refunded_quantity(p_sale_item_id uuid)
returns numeric
language sql
stable
as $$
  select coalesce(sum(ri.quantity), 0)::numeric
  from public.sale_refund_items ri
  where ri.sale_item_id = p_sale_item_id;
$$;

-- ---------------------------------------------------------------------------
-- take_back: the units of one sold line, returned to the batches they left.
--
-- Walks that line's allocation in the order it was consumed, stepping over whatever has
-- already been handed back, and takes the next p_quantity from there. That is what makes a
-- second partial refund come off the right batch instead of the first one again.
--
-- Sales taken before batches existed have no allocation. They are still refundable: the
-- units go back on the shelf and are costed at the price recorded on the line itself, which
-- is exactly what that sale was costed at in the first place.
-- ---------------------------------------------------------------------------
create or replace function public.take_back(
  p_sale_item_id uuid,
  p_quantity     numeric,
  p_already      numeric
) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_alloc  record;
  v_skip   numeric := coalesce(p_already, 0);
  v_want   numeric := p_quantity;
  v_free   numeric;
  v_take   numeric;
  v_cost   numeric := 0;
  v_return jsonb := '[]'::jsonb;
  v_unit   integer;
begin
  for v_alloc in
    select * from public.sale_item_batches
     where sale_item_id = p_sale_item_id
     order by created_at, id
  loop
    exit when v_want <= 0;

    v_free := v_alloc.quantity;

    if v_skip > 0 then
      v_free := v_free - least(v_skip, v_alloc.quantity);
      v_skip := v_skip - least(v_skip, v_alloc.quantity);
    end if;

    if v_free <= 0 then
      continue;
    end if;

    v_take := least(v_free, v_want);
    v_cost := v_cost + v_take * v_alloc.unit_cost_cents;
    v_want := v_want - v_take;

    if v_alloc.batch_id is not null then
      v_return := v_return || jsonb_build_object(
        'batch_id', v_alloc.batch_id,
        'quantity', v_take
      );
    end if;
  end loop;

  -- Nothing left to draw on: an older sale, or a batch that has since been collapsed away.
  if v_want > 0 then
    select unit_cost_cents into v_unit from public.sale_items where id = p_sale_item_id;
    v_cost := v_cost + v_want * coalesce(v_unit, 0);
  end if;

  perform public.return_to_batches(v_return);

  return jsonb_build_object('cost_cents', round(v_cost), 'returned', v_return);
end;
$$;

-- ---------------------------------------------------------------------------
-- void_sale: the whole thing, undone.
-- ---------------------------------------------------------------------------
create or replace function public.void_sale(p_sale_id uuid, p_reason text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_sale  public.sales%rowtype;
  v_item  record;
  v_back  jsonb;
  v_lines integer := 0;
  v_units numeric := 0;
begin
  if auth.uid() is null then
    raise exception 'You must be signed in to void a sale' using errcode = '42501';
  end if;

  select * into v_sale from public.sales where id = p_sale_id for update;

  if not found then
    raise exception 'That sale no longer exists' using errcode = '23503';
  end if;

  if v_sale.voided_at is not null then
    raise exception 'That sale was already voided' using errcode = 'BS003';
  end if;

  -- A sale that has been partly handed back is a history, not a mistake. Erasing it would
  -- take the refund with it and leave the cash box holding a payment that never reversed.
  if exists (select 1 from public.sale_refunds where sale_id = p_sale_id) then
    raise exception 'That sale has already been refunded in part, so it cannot be voided'
      using errcode = 'BS003';
  end if;

  for v_item in
    select * from public.sale_items where sale_id = p_sale_id order by id
  loop
    v_back := public.take_back(v_item.id, v_item.quantity, 0);

    if v_item.product_id is not null then
      update public.products
         set quantity_in_stock = quantity_in_stock + v_item.quantity
       where id = v_item.product_id;

      perform public.sync_cost_from_batches(v_item.product_id);

      insert into public.stock_movements (product_id, delta, reason, sale_id, note, created_by)
      values (v_item.product_id, v_item.quantity, 'void', p_sale_id,
              nullif(btrim(coalesce(p_reason, '')), ''), auth.uid());
    end if;

    v_lines := v_lines + 1;
    v_units := v_units + v_item.quantity;
  end loop;

  if v_sale.total_cents > 0 then
    insert into public.cash_movements (kind, amount_cents, sale_id, note, created_by)
    values ('void', -v_sale.total_cents, p_sale_id,
            nullif(btrim(coalesce(p_reason, '')), ''), auth.uid());
  end if;

  update public.sales
     set voided_at   = now(),
         voided_by   = auth.uid(),
         void_reason = nullif(btrim(coalesce(p_reason, '')), '')
   where id = p_sale_id;

  return jsonb_build_object(
    'sale_id',      p_sale_id,
    'lines',        v_lines,
    'units',        v_units,
    'total_cents',  v_sale.total_cents
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- refund_sale: some of it, back over the counter, today.
--
-- p_items is [{ "sale_item_id": uuid, "quantity": number }]. A line can be returned more
-- than once as long as the total never exceeds what was sold, which is checked against the
-- refunds already recorded rather than trusted from the caller.
-- ---------------------------------------------------------------------------
create or replace function public.refund_sale(
  p_sale_id uuid,
  p_items   jsonb,
  p_reason  text default null
) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_sale      public.sales%rowtype;
  v_refund_id uuid := gen_random_uuid();
  v_line      record;
  v_item      public.sale_items%rowtype;
  v_already   numeric;
  v_back      jsonb;
  v_gross     bigint;
  v_net       bigint;
  v_cost      bigint;
  v_line_net  bigint;
  v_sum_net   bigint := 0;
  v_sum_cost  bigint := 0;
  v_sum_units numeric := 0;
begin
  if auth.uid() is null then
    raise exception 'You must be signed in to refund a sale' using errcode = '42501';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Choose what is being returned' using errcode = '22023';
  end if;

  select * into v_sale from public.sales where id = p_sale_id for update;

  if not found then
    raise exception 'That sale no longer exists' using errcode = '23503';
  end if;

  if v_sale.voided_at is not null then
    raise exception 'That sale was voided, so there is nothing to refund' using errcode = 'BS003';
  end if;

  insert into public.sale_refunds (id, sale_id, reason, created_by)
  values (v_refund_id, p_sale_id, nullif(btrim(coalesce(p_reason, '')), ''), auth.uid());

  for v_line in
    select (elem ->> 'sale_item_id')::uuid as sale_item_id,
           sum((elem ->> 'quantity')::numeric) as quantity
    from jsonb_array_elements(p_items) as elem
    group by 1
    order by 1
  loop
    if v_line.quantity is null or v_line.quantity <= 0 then
      raise exception 'A returned quantity must be greater than zero' using errcode = '22023';
    end if;

    select * into v_item
      from public.sale_items
     where id = v_line.sale_item_id and sale_id = p_sale_id
     for update;

    if not found then
      raise exception 'That line is not part of this sale' using errcode = '23503';
    end if;

    v_already := public.refunded_quantity(v_item.id);

    if v_already + v_line.quantity > v_item.quantity then
      raise exception 'Only % of "%" can still be returned, % asked for',
        v_item.quantity - v_already, v_item.product_name, v_line.quantity
        using errcode = 'BS004';
    end if;

    -- The line's share of the basket discount, spread the same way the reports spread it, so
    -- a fully returned sale hands back exactly what was taken and not a cent more.
    v_line_net := v_item.line_total_cents - case
      when v_sale.subtotal_cents > 0
        then round(v_sale.discount_cents::numeric * v_item.line_total_cents / v_sale.subtotal_cents)
      else 0
    end;

    v_gross := round(v_item.unit_price_cents::numeric * v_line.quantity);
    v_net   := round(v_line_net::numeric * v_line.quantity / v_item.quantity);

    v_back := public.take_back(v_item.id, v_line.quantity, v_already);
    v_cost := (v_back ->> 'cost_cents')::bigint;

    if v_item.product_id is not null then
      update public.products
         set quantity_in_stock = quantity_in_stock + v_line.quantity
       where id = v_item.product_id;

      perform public.sync_cost_from_batches(v_item.product_id);

      insert into public.stock_movements (product_id, delta, reason, sale_id, note, created_by)
      values (v_item.product_id, v_line.quantity, 'refund', p_sale_id,
              nullif(btrim(coalesce(p_reason, '')), ''), auth.uid());
    end if;

    insert into public.sale_refund_items (
      refund_id, sale_item_id, product_id, product_name, barcode, category_name, unit,
      quantity, unit_price_cents, unit_cost_cents, gross_cents, net_cents, cost_cents
    ) values (
      v_refund_id, v_item.id, v_item.product_id, v_item.product_name, v_item.barcode,
      v_item.category_name, v_item.unit, v_line.quantity, v_item.unit_price_cents,
      case when v_line.quantity > 0 then round(v_cost / v_line.quantity) else 0 end,
      v_gross, v_net, v_cost
    );

    v_sum_net   := v_sum_net + v_net;
    v_sum_cost  := v_sum_cost + v_cost;
    v_sum_units := v_sum_units + v_line.quantity;
  end loop;

  update public.sale_refunds
     set total_cents  = v_sum_net,
         cost_cents   = v_sum_cost,
         profit_cents = v_sum_net - v_sum_cost,
         item_count   = v_sum_units
   where id = v_refund_id;

  if v_sum_net > 0 then
    insert into public.cash_movements (kind, amount_cents, sale_id, note, created_by)
    values ('refund', -v_sum_net, p_sale_id,
            nullif(btrim(coalesce(p_reason, '')), ''), auth.uid());
  end if;

  return jsonb_build_object(
    'refund_id',   v_refund_id,
    'total_cents', v_sum_net,
    'units',       v_sum_units
  );
end;
$$;

do $$
declare fn text;
begin
  foreach fn in array array[
    'public.refunded_quantity(uuid)',
    'public.take_back(uuid, numeric, numeric)',
    'public.void_sale(uuid, text)',
    'public.refund_sale(uuid, jsonb, text)'
  ]
  loop
    execute format('revoke all on function %s from public, anon', fn);
  end loop;
end;
$$;

grant execute on function public.refunded_quantity(uuid)          to authenticated;
grant execute on function public.void_sale(uuid, text)            to authenticated;
grant execute on function public.refund_sale(uuid, jsonb, text)   to authenticated;

-- ==========================================================================
-- 20260830090600_reports_net.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- Reporting, once a sale can be taken back.
--
-- Two rules, and they are different on purpose.
--
-- A voided sale is filtered out wherever it appears. It did not happen, so it is not in the
-- figures for the day it was rung up on, and re-reading last week gives the corrected
-- picture rather than the one that was wrong at the time.
--
-- A refund is a dated event of its own and lands in the period it happened in. That keeps
-- today's report agreeing with today's cash drawer, which is the comparison the shop
-- actually makes, and it stops a month that has already been read changing underneath
-- whoever read it.
--
-- The mechanism for the second one is the fact view: refunded lines come back through it as
-- negative rows stamped with the refund date. Everything built on top then nets out without
-- knowing anything about refunds at all.
-- ---------------------------------------------------------------------------

-- Dropped rather than replaced: the view gains a column and both halves of the union have
-- to agree on types, neither of which CREATE OR REPLACE VIEW will do. Nothing depends on it
-- structurally, since every reporting function holds its query as text.
drop view if exists public.sale_line_facts;

create view public.sale_line_facts
with (security_invoker = on) as
select
  si.id,
  si.sale_id,
  s.sold_at,
  s.payment_currency,
  si.product_id,
  si.product_name,
  si.barcode,
  coalesce(si.category_name, 'Uncategorised') as category_name,
  si.unit,
  si.quantity::numeric(12,3) as quantity,
  si.unit_price_cents,
  si.unit_cost_cents,
  si.line_total_cents::bigint as gross_cents,
  si.line_cost_cents::bigint  as cost_cents,
  (si.line_total_cents - case
     when s.subtotal_cents > 0
       then round(s.discount_cents::numeric * si.line_total_cents / s.subtotal_cents)
     else 0
   end)::bigint as net_cents,
  (si.line_total_cents - case
     when s.subtotal_cents > 0
       then round(s.discount_cents::numeric * si.line_total_cents / s.subtotal_cents)
     else 0
   end - si.line_cost_cents)::bigint as net_profit_cents,
  false as is_refund
from public.sale_items si
join public.sales s on s.id = si.sale_id
where s.voided_at is null

union all

-- Goods handed back, as negatives on the day they came back.
select
  ri.id,
  r.sale_id,
  r.refunded_at as sold_at,
  s.payment_currency,
  ri.product_id,
  ri.product_name,
  ri.barcode,
  coalesce(ri.category_name, 'Uncategorised') as category_name,
  ri.unit,
  (-ri.quantity)::numeric(12,3),
  ri.unit_price_cents,
  ri.unit_cost_cents,
  (-ri.gross_cents)::bigint,
  (-ri.cost_cents)::bigint,
  (-ri.net_cents)::bigint,
  (-(ri.net_cents - ri.cost_cents))::bigint,
  true
from public.sale_refund_items ri
join public.sale_refunds r on r.id = ri.refund_id
join public.sales s        on s.id = r.sale_id
where s.voided_at is null;

grant select on public.sale_line_facts to authenticated;

-- ---------------------------------------------------------------------------
-- The headline figures, with what was handed back shown rather than buried.
--
-- Refunds are netted off the totals and also reported on their own line, because "we took
-- $400" and "we took $520 and gave $120 back" are the same balance and a different day.
-- ---------------------------------------------------------------------------
drop function if exists public.report_summary(timestamptz, timestamptz);

create or replace function public.report_summary(p_from timestamptz, p_to timestamptz)
returns table (
  total_sales_cents    bigint,
  total_cost_cents     bigint,
  total_profit_cents   bigint,
  total_discount_cents bigint,
  transaction_count    bigint,
  items_sold           numeric,
  paid_usd_cents       bigint,
  paid_lbp_cents       bigint,
  refunded_cents       bigint,
  refund_count         bigint,
  voided_cents         bigint,
  voided_count         bigint
)
language sql
stable
as $$
  with sold as (
    select
      coalesce(sum(total_cents), 0)::bigint      as total,
      coalesce(sum(total_cost_cents), 0)::bigint as cost,
      coalesce(sum(profit_cents), 0)::bigint     as profit,
      coalesce(sum(discount_cents), 0)::bigint   as discount,
      count(*)::bigint                           as txns,
      coalesce(sum(item_count), 0)::numeric      as items,
      coalesce(sum(total_cents) filter (where payment_currency = 'USD'), 0)::bigint as usd,
      coalesce(sum(total_cents) filter (where payment_currency = 'LBP'), 0)::bigint as lbp
    from public.sales
    where sold_at >= p_from and sold_at < p_to
      and voided_at is null
  ),
  back as (
    select
      coalesce(sum(r.total_cents), 0)::bigint  as total,
      coalesce(sum(r.cost_cents), 0)::bigint   as cost,
      coalesce(sum(r.profit_cents), 0)::bigint as profit,
      count(*)::bigint                         as refunds,
      coalesce(sum(r.item_count), 0)::numeric  as items,
      coalesce(sum(r.total_cents) filter (where s.payment_currency = 'USD'), 0)::bigint as usd,
      coalesce(sum(r.total_cents) filter (where s.payment_currency = 'LBP'), 0)::bigint as lbp
    from public.sale_refunds r
    join public.sales s on s.id = r.sale_id
    where r.refunded_at >= p_from and r.refunded_at < p_to
      and s.voided_at is null
  ),
  killed as (
    select coalesce(sum(total_cents), 0)::bigint as total, count(*)::bigint as txns
    from public.sales
    where voided_at >= p_from and voided_at < p_to
  )
  select
    sold.total - back.total,
    sold.cost - back.cost,
    sold.profit - back.profit,
    sold.discount,
    sold.txns,
    sold.items - back.items,
    sold.usd - back.usd,
    sold.lbp - back.lbp,
    back.total,
    back.refunds,
    killed.total,
    killed.txns
  from sold, back, killed;
$$;

-- ---------------------------------------------------------------------------
-- The trend, with refunds pulling their bucket down on the day they happened.
-- ---------------------------------------------------------------------------
create or replace function public.report_time_series(
  p_from     timestamptz,
  p_to       timestamptz,
  p_bucket   text default 'daily',
  p_timezone text default 'UTC'
)
returns table (
  bucket_start      timestamptz,
  sales_cents       bigint,
  profit_cents      bigint,
  transaction_count bigint,
  items_sold        numeric
)
language plpgsql
stable
as $$
declare
  v_unit text;
  v_step interval;
begin
  if p_bucket not in ('daily', 'weekly', 'monthly') then
    raise exception 'Unknown report bucket %', p_bucket using errcode = '22023';
  end if;

  v_unit := case p_bucket when 'weekly' then 'week' when 'monthly' then 'month' else 'day' end;
  v_step := case v_unit when 'week' then interval '1 week'
                        when 'month' then interval '1 month'
                        else interval '1 day' end;

  return query
  with periods as (
    select generate_series(
             date_trunc(v_unit, (p_from at time zone p_timezone)),
             date_trunc(v_unit, ((p_to - interval '1 microsecond') at time zone p_timezone)),
             v_step
           ) as bucket
  ),
  totals as (
    select date_trunc(v_unit, (s.sold_at at time zone p_timezone)) as bucket,
           sum(s.total_cents)::bigint  as sales,
           sum(s.profit_cents)::bigint as profit,
           count(*)::bigint            as txns,
           sum(s.item_count)::numeric  as items
    from public.sales s
    where s.sold_at >= p_from and s.sold_at < p_to
      and s.voided_at is null
    group by 1
  ),
  backs as (
    select date_trunc(v_unit, (r.refunded_at at time zone p_timezone)) as bucket,
           sum(r.total_cents)::bigint  as sales,
           sum(r.profit_cents)::bigint as profit,
           sum(r.item_count)::numeric  as items
    from public.sale_refunds r
    join public.sales s on s.id = r.sale_id
    where r.refunded_at >= p_from and r.refunded_at < p_to
      and s.voided_at is null
    group by 1
  )
  select (periods.bucket at time zone p_timezone)::timestamptz,
         (coalesce(totals.sales, 0) - coalesce(backs.sales, 0))::bigint,
         (coalesce(totals.profit, 0) - coalesce(backs.profit, 0))::bigint,
         coalesce(totals.txns, 0)::bigint,
         (coalesce(totals.items, 0) - coalesce(backs.items, 0))::numeric
  from periods
  left join totals on totals.bucket = periods.bucket
  left join backs  on backs.bucket  = periods.bucket
  order by periods.bucket;
end;
$$;

-- ---------------------------------------------------------------------------
-- list_sales: the till roll, which the shop needs before it can void anything.
--
-- Voided sales stay in the list, struck through rather than vanished, because the question
-- "what happened to that sale" has to have an answer somewhere.
-- ---------------------------------------------------------------------------
create or replace function public.list_sales(
  p_from  timestamptz default null,
  p_to    timestamptz default null,
  p_limit integer default 50
)
returns table (
  id               uuid,
  sold_at          timestamptz,
  total_cents      bigint,
  profit_cents     bigint,
  item_count       numeric,
  payment_currency text,
  total_lbp        numeric,
  note             text,
  voided_at        timestamptz,
  void_reason      text,
  refunded_cents   bigint,
  refunded_items   numeric,
  refund_count     bigint
)
language sql
stable
as $$
  select s.id,
         s.sold_at,
         s.total_cents::bigint,
         s.profit_cents::bigint,
         s.item_count,
         s.payment_currency,
         s.total_lbp,
         s.note,
         s.voided_at,
         s.void_reason,
         coalesce(r.total, 0)::bigint,
         coalesce(r.items, 0)::numeric,
         coalesce(r.count, 0)::bigint
  from public.sales s
  left join lateral (
    select sum(total_cents) as total, sum(item_count) as items, count(*) as count
    from public.sale_refunds where sale_id = s.id
  ) r on true
  where (p_from is null or s.sold_at >= p_from)
    and (p_to is null or s.sold_at < p_to)
  order by s.sold_at desc, s.id desc
  limit greatest(coalesce(p_limit, 50), 1);
$$;

-- One sale in full, with what has already gone back per line, which is what the refund
-- screen needs to know before it can offer anything.
--
-- net_cents is the line less its share of the basket discount, and it is here because the
-- screen has to be able to say what a return is worth before it happens. Offering to hand
-- back the undiscounted price and then handing back less is the kind of small lie that
-- makes a shop stop trusting the till.
drop function if exists public.get_sale_lines(uuid);

create or replace function public.get_sale_lines(p_sale_id uuid)
returns table (
  id                uuid,
  product_id        uuid,
  product_name      text,
  barcode           text,
  category_name     text,
  unit              text,
  quantity          numeric,
  unit_price_cents  integer,
  unit_cost_cents   integer,
  line_total_cents  bigint,
  net_cents         bigint,
  refunded_quantity numeric
)
language sql
stable
as $$
  select si.id,
         si.product_id,
         si.product_name,
         si.barcode,
         si.category_name,
         si.unit,
         si.quantity,
         si.unit_price_cents,
         si.unit_cost_cents,
         si.line_total_cents::bigint,
         (si.line_total_cents - case
            when s.subtotal_cents > 0
              then round(s.discount_cents::numeric * si.line_total_cents / s.subtotal_cents)
            else 0
          end)::bigint,
         public.refunded_quantity(si.id)
  from public.sale_items si
  join public.sales s on s.id = si.sale_id
  where si.sale_id = p_sale_id
  order by si.id;
$$;

do $$
declare fn text;
begin
  foreach fn in array array[
    'public.report_summary(timestamptz, timestamptz)',
    'public.report_time_series(timestamptz, timestamptz, text, text)',
    'public.list_sales(timestamptz, timestamptz, integer)',
    'public.get_sale_lines(uuid)'
  ]
  loop
    execute format('revoke all on function %s from public, anon', fn);
    execute format('grant execute on function %s to authenticated', fn);
  end loop;
end;
$$;

-- ==========================================================================
-- 20260830090700_grants_reset.sql
-- ==========================================================================
-- ---------------------------------------------------------------------------
-- The new tables, locked down the same way the old ones are.
--
-- Every one of them is money or the record of it, and every one is written only by a
-- SECURITY DEFINER function. So the client may read them and nothing more: a device can show
-- the price history but cannot invent one, and can show what a batch cost but cannot decide
-- it. The grants mirror the policies exactly, and each is preceded by a revoke because
-- Supabase hands new tables a blanket GRANT ALL that would otherwise leave TRUNCATE behind.
-- ---------------------------------------------------------------------------

alter table public.stock_batches         enable row level security;
alter table public.product_price_history enable row level security;
alter table public.sale_item_batches     enable row level security;
alter table public.sale_refunds          enable row level security;
alter table public.sale_refund_items     enable row level security;

do $$
declare t text;
begin
  foreach t in array array[
    'stock_batches', 'product_price_history', 'sale_item_batches',
    'sale_refunds', 'sale_refund_items'
  ]
  loop
    execute format('drop policy if exists %I_read on public.%I', t, t);
    execute format(
      'create policy %I_read on public.%I for select to authenticated using (true)', t, t
    );
    execute format('revoke all on public.%I from authenticated', t);
    execute format('grant select on public.%I to authenticated', t);
    execute format('revoke all on public.%I from anon', t);
  end loop;
end;
$$;

-- ---------------------------------------------------------------------------
-- reset_shop, now emptying the tables that did not exist when it was written.
--
-- Most of them would fall away with their parents anyway, but naming them keeps the counts
-- honest: the screen tells the shop exactly what it removed, and a table missing from this
-- list is a table that silently reports zero.
-- ---------------------------------------------------------------------------
create or replace function public.reset_shop(p_confirm text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_counts jsonb;
begin
  if auth.uid() is null then
    raise exception 'You must be signed in to reset the shop' using errcode = '42501';
  end if;

  if p_confirm is distinct from 'RESET' then
    raise exception 'Reset needs the word RESET to confirm it' using errcode = '22023';
  end if;

  select jsonb_build_object(
    'sales',      (select count(*) from public.sales),
    'sale_items', (select count(*) from public.sale_items),
    'stock',      (select count(*) from public.stock_movements),
    'cash',       (select count(*) from public.cash_movements),
    'products',   (select count(*) from public.products),
    'categories', (select count(*) from public.categories),
    'batches',    (select count(*) from public.stock_batches),
    'prices',     (select count(*) from public.product_price_history),
    'refunds',    (select count(*) from public.sale_refunds)
  ) into v_counts;

  /*
    Every one of these carries `where true`, which looks redundant and is not.

    Supabase preloads the safeupdate extension, which refuses any DELETE or UPDATE without a
    WHERE clause so that a mistyped statement cannot empty a table. A plain Postgres does not,
    which is how this shipped passing every local test and then failed in the shop with
    "DELETE requires a WHERE clause". The guard is worth keeping; this really does mean to
    empty the table, so it says so out loud rather than by omission.

    Children before parents throughout, so nothing depends on which foreign keys happen to
    cascade and which merely null out.
  */
  delete from public.sale_refund_items    where true;
  delete from public.sale_refunds         where true;
  delete from public.sale_item_batches    where true;
  delete from public.cash_movements       where true;
  delete from public.stock_movements      where true;
  delete from public.sale_items           where true;
  delete from public.sales                where true;
  delete from public.product_price_history where true;
  delete from public.stock_batches        where true;
  delete from public.products             where true;
  delete from public.categories           where true;

  return v_counts;
end;
$$;

revoke all on function public.reset_shop(text) from public, anon;
grant execute on function public.reset_shop(text) to authenticated;

-- Anonymous callers keep getting nothing, including from everything added above.
revoke all on all tables    in schema public from anon;
revoke all on all sequences in schema public from anon;
revoke all on all functions in schema public from anon;
